from collections import deque

def solve(grid, start, goal):
    def neighbors(row, col):
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = row + dr, col + dc
            if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]) and grid[nr][nc] == '.':
                yield nr, nc

    def bfs(start, visited, parent, direction):
        queue = deque([start])
        visited[start] = True
        while queue:
            row, col = queue.popleft()
            for nr, nc in neighbors(row, col):
                if not visited.get((nr, nc)):
                    visited[(nr, nc)] = True
                    parent[(nr, nc)] = (row, col)
                    queue.append((nr, nc))
                    if direction and (nr, nc) in reverse_visited:
                        return (nr, nc)
                    if not direction and (nr, nc) in forward_visited:
                        return (nr, nc)
        return None

    if not grid or not grid[0]:
        return []
    rows, cols = len(grid), len(grid[0])
    if not (0 <= start[0] < rows and 0 <= start[1] < cols and grid[start[0]][start[1]] == '.'):
        return []
    if not (0 <= goal[0] < rows and 0 <= goal[1] < cols and grid[goal[0]][goal[1]] == '.'):
        return []
    if start == goal:
        return [start]

    forward_visited, reverse_visited = {start: True}, {goal: True}
    forward_parent, reverse_parent = {}, {}
    meet = None

    while True:
        mid = bfs(start, forward_visited, forward_parent, True)
        if mid:
            meet = mid
            break
        mid = bfs(goal, reverse_visited, reverse_parent, False)
        if mid:
            meet = mid
            break
        if not forward_visited or not reverse_visited:
            return []

    path = []
    curr = meet
    while curr != start:
        path.append(curr)
        curr = forward_parent[curr]
    path.append(start)
    path.reverse()

    curr = meet
    while curr != goal:
        curr = reverse_parent[curr]
        path.append(curr)
    path.append(goal)
    return path
