def solve(grid, start, goal):
    if not grid or not grid[0]:
        return []
    rows, cols = len(grid), len(grid[0])
    if not (0 <= start[0] < rows and 0 <= start[1] < cols and 0 <= goal[0] < rows and 0 <= goal[1] < cols):
        return []
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []
    if start == goal:
        return [start]

    forward_queue = deque([start])
    backward_queue = deque([goal])
    forward_visited = {start}
    backward_visited = {goal}
    forward_parent = {start: None}
    backward_parent = {goal: None}
    direction = 0  # 0 for forward, 1 for backward

    while forward_queue and backward_queue:
        if direction == 0:
            current = forward_queue.popleft()
            neighbors = [
                (current[0]-1, current[1]),
                (current[0]+1, current[1]),
                (current[0], current[1]-1),
                (current[0], current[1]+1)
            ]
            for neighbor in neighbors:
                if 0 <= neighbor[0] < rows and 0 <= neighbor[1] < cols and grid[neighbor[0]][neighbor[1]] == '.':
                    if neighbor not in forward_visited:
                        forward_visited.add(neighbor)
                        forward_parent[neighbor] = current
                        forward_queue.append(neighbor)
                        if neighbor in backward_visited:
                            return build_path(forward_parent, backward_parent, current, neighbor)
            direction = 1
        else:
            current = backward_queue.popleft()
            neighbors = [
                (current[0]-1, current[1]),
                (current[0]+1, current[1]),
                (current[0], current[1]-1),
                (current[0], current[1]+1)
            ]
            for neighbor in neighbors:
                if 0 <= neighbor[0] < rows and 0 <= neighbor[1] < cols and grid[neighbor[0]][neighbor[1]] == '.':
                    if neighbor not in backward_visited:
                        backward_visited.add(neighbor)
                        backward_parent[neighbor] = current
                        backward_queue.append(neighbor)
                        if neighbor in forward_visited:
                            return build_path(forward_parent, backward_parent, neighbor, current)
            direction = 0
    return []

def build_path(forward_parent, backward_parent, meeting_point, goal):
    path_forward = []
    current = meeting_point
    while current is not None:
        path_forward.append(current)
        current = forward_parent[current]
    path_forward.reverse()

    path_backward = []
    current = goal
    while current is not None:
        path_backward.append(current)
        current = backward_parent[current]
    path_backward.pop(0)  # remove the duplicate meeting point
    return path_forward + path_backward
