from collections import deque

def solve(grid, start, goal):
    if not grid or not grid[0]:
        return []
    rows, cols = len(grid), len(grid[0])
    if start == goal and grid[start[0]][start[1]] == '.':
        return [start]
    if not is_free(grid, start) or not is_free(grid, goal):
        return []

    def neighbors(r, c):
        directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.':
                yield nr, nc

    def is_free(grid, pos):
        r, c = pos
        return 0 <= r < len(grid) and 0 <= c < len(grid[0]) and grid[r][c] == '.'

    forward = {start: None}
    backward = {goal: None}
    forward_q = deque([start])
    backward_q = deque([goal])

    while forward and backward and forward_q and backward_q:
        if len(forward_q) <= len(backward_q):
            if not expand(frontier=forward_q, visited=forward, other=backward, grid=grid, neighbors=neighbors):
                return []
        else:
            if not expand(frontier=backward_q, visited=backward, other=forward, grid=grid, neighbors=neighbors):
                return []
        if goal in forward or start in backward:
            path = []
            if goal in forward:
                path = build_path(forward, start, goal)
            else:
                path = build_path(backward, goal, start)[::-1]
            return path.reverse() if path and path[-1] == start else path if path else []

    return []

def expand(frontier, visited, other, grid, neighbors):
    for _ in range(len(frontier)):
        current = frontier.popleft()
        for next_cell in neighbors(*current):
            if next_cell not in visited:
                visited[next_cell] = current
                frontier.append(next_cell)
                if next_cell in other:
                    return False  # A connection is found
    return True

def build_path(visited, start, end):
    path = []
    current = end
    while current:
        path.append(current)
        current = visited[current]
    if current is None and path[-1] == start:
        return path[::-1]
    return path[::-1] if path and path[-1] == start else []
