        r, c = pos
        moves = [(-1, 0), (1, 0), (0, -1), (0, 1)]
        for dr, dc in moves:
            nr, nc = r + dr, c + dc
            if (0 <= nr < len(grid) and 0 <= nc < len(grid[0]) and
                grid[nr][nc] == '.'):
                yield (nr, nc)

    def bfs(start, from_start):
        q = deque()
        q.append(start)
        from_start[start] = 0
        while q:
            pos = q.popleft()
            for n in neighbors(pos):
                if n not in from_start:
                    from_start[n] = from_start[pos] + 1
                    q.append(n)

    def find_intersection(from_start, from_goal):
        for pos in from_start:
            if pos in from_goal:
                return pos
        return None

    def reconstruct_path(from_start, from_goal, meet):
        path_start = [meet]
        path_goal = [meet]
        pos = meet
        while pos != start:
            for n in neighbors(pos):
                if from_start[n] == from_start[pos] - 1:
                    path_start.insert(0, n)
                    pos = n
                    break
        pos = meet
        while pos != goal:
            for n in neighbors(pos):
                if from_goal[n] == from_goal[pos] - 1:
                    path_goal.append(n)
                    pos = n
                    break
        path_start.extend(path_goal[1:])
        return path_start

    from_start = {start: 0}
    from_goal = {goal: 0}
    frontier_start = deque([start])
    frontier_goal = deque([goal])

    while frontier_start and frontier_start[0] not in from_goal and frontier_goal and frontier_goal[0] not in from_start:
        for _ in range(len(frontier_start)):
            pos = frontier_start.popleft()
            for n in neighbors(pos):
                if n not in from_start or from_start[n] > from_start[pos] + 1:
                    from_start[n] = from_start[pos] + 1
                    frontier_start.append(n)
        for _ in range(len(frontier_goal)):
            pos = frontier_goal.popleft()
            for n in neighbors(pos):
                if n not in from_goal or from_goal[n] > from_goal[pos] + 1:
                    from_goal[n] = from_goal[pos] + 1
                    frontier_goal.append(n)

    meet = find_intersection(from_start, from_goal)
    if not meet:
        return []
    return reconstruct_path(from_start, from_goal, meet)
