def solve(grid, start, goal):
    if start == goal:
        return [start]

    rows, cols = len(grid), len(grid[0])
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []

    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    def bfs(frontier, visited, parent, direction):
        while frontier:
            r, c = frontier.popleft()
            for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                nr, nc = r + dr, c + dc
                if is_valid(nr, nc) and (nr, nc) not in visited:
                    visited[(nr, nc)] = direction
                    parent[(nr, nc)] = (r, c)
                    frontier.append((nr, nc))
                    if (nr, nc) in other_visited:
                        return reconstruct_path((nr, nc), parent, other_visited)
        return None

    def reconstruct_path(meet_point, parent, other_visited):
        path = [meet_point]
        while path[-1] != start:
            parent_node = parent.get(path[-1])
            if parent_node is None:
                return None
            path.append(parent_node)
        path.reverse()
        current = path[-1] if path else None
        while current != meet_point:
            next_node = other_visited.get(current)
            if next_node is None:
                return None
            path.append(next_node)
            current = next_node
        return path

    forward_queue = deque([start])
    backward_queue = deque([goal])
    forward_visited = {start: 'forward'}
    backward_visited = {goal: 'backward'}
    forward_parent = {}
    backward_parent = {}

    while forward_queue and backward_queue:
        result = bfs(forward_queue, forward_visited, forward_parent, 'forward')
        if result:
            return result
        result = bfs(backward_queue, backward_visited, backward_parent, 'backward')
        if result:
            return result

    return []
