        return []

    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    visited_start = {start}
    visited_goal = {goal}
    parent_start = {}
    parent_goal = {}
    queue_start = deque([start])
    queue_goal = deque([goal])

    while queue_start and queue_end := queue_goal:
        if queue_start:
            current = queue_start.popleft()
            for dr, dc in directions:
                r, c = current[0] + dr, current[1] + dc
                if 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.' and (r, c) not in visited_start:
                    visited_start.add((r, c))
                    parent_start[(r, c)] = current
                    if (r, c) in visited_goal:
                        return combine_paths(parent_start, parent_goal, start, (r, c), goal)
                    queue_start.append((r, c))

        if queue_end:
            current = queue_goal.popleft()
            for dr, dc in directions:
                r, c = current[0] + dr, current[1] + dc
                if 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.' and (r, c) not in visited_goal:
                    visited_goal.add((r, c))
                    parent_goal[(r, c)] = current
                    if (r, c) in visited_start:
                        return combine_paths(parent_start, parent_goal, start, (r, c), goal)
                    queue_goal.append((r, c))

    return []

def combine_paths(parent_start, parent_goal, start, meeting_point, goal):
    path_forward = []
    current = meeting_point
    while current != start:
        path_forward.append(current)
        current = parent_start[current]
    path_forward.append(start)
    path_forward.reverse()

    path_backward = []
    current = meeting_point
    while current != goal:
        path_backward.append(current)
        current = parent_goal[current]
    path_backward.append(goal)

    return path_forward + path_backward
