from collections import deque

def solve(grid, start, goal):
    def is_free(r, c):
        return 0 <= r < len(grid) and 0 <= c < len(grid[0]) and grid[r][c] == '.'

    def get_neighbors(r, c):
        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
        return [(r + dr, c + dc) for dr, dc in directions if is_free(r + dr, c + dc)]

    if start == goal and is_free(*start):
        return [start]
    if not is_free(*start) or not is_free(*goal):
        return []

    # Bidirectional BFS
    def bfs(starts):
        queue = deque(starts)
        visited = {s: None for s in starts}
        while queue:
            current = queue.popleft()
            for neighbor in get_neighbors(*current):
                if neighbor not in visited:
                    visited[neighbor] = current
                    queue.append(neighbor)
        return visited

    # BFS from start and goal
    start_visited = bfs([start])
    if goal in start_visited:
        return reconstruct_path(start_visited, start, goal)

    goal_visited = bfs([goal])
    common = set(start_visited.keys()) & set(goal_visited.keys())
    if not common:
        return []

    # Find the first common node
    meeting_point = common.pop()
    path_forward = reconstruct_path(start_visited, start, meeting_point)
    path_backward = reconstruct_path(goal_visited, goal, meeting_point, reverse=True)
    return path_forward + path_backward[1:]


def reconstruct_path(visited, start, end, reverse=False):
    path = []
    current = end
    while current != start:
        path.append(current)
        current = visited[current]
        if current is None:
            return []
    path.append(start)
    return path[::-1] if reverse else path
