                    frontier.append((nr, nc))
                    parent[(nr, nc)] = (row, col)
                    reverse_parent[(row, col)] = (nr, nc)
                    if (nr, nc) == goal or (nr, nc) in reverse_parent:
                        return True
        return False

    start_queue = deque([start])
    goal_queue = deque([goal])

    start_visited = {start: None}
    goal_visited = {goal: None}

    start_parent = {}
    goal_parent = {}

    while start_queue and goal_queue:
        if bfs(start_queue, start_visited, start_parent, goal_parent):
            return build_path(start, goal, start_parent, goal_parent)
        if bfs(goal_queue, goal_visited, goal_parent, start_parent):
            return build_path(start, goal, start_parent, goal_parent)

    return []

def build_path(start, goal, forward, backward):
    if goal not in forward and start not in backward:
        return []

    path = [goal]
    current = goal
    while current in forward:
        current = forward[current]
        path.append(current)
        if current == start:
            path.reverse()
            return path

    current = start
    while current in backward:
        current = backward[current]
        path.insert(0, current)
        if current == goal:
            return path

    return []
