def solve(grid, start, goal):
    rows, cols = len(grid), len(grid[0])
    if (start == goal) and (grid[start[0]][start[1]] == '.'):
        return [start]
    if (grid[start[0]][start[1]] == '#') or (grid[goal[0]][goal[1]] == '#'):
        return []

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def bfs(starts, is_forward):
        q = deque()
        parent = {}
        for s in starts:
            q.append(s)
            parent[s] = None
        while q:
            cell = q.popleft()
            r, c = cell
            for dr, dc in directions:
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.':
                    neighbor = (nr, nc)
                    if neighbor not in parent:
                        parent[neighbor] = cell
                        if is_forward:
                            if neighbor == goal:
                                return parent, neighbor
                        else:
                            if neighbor == start:
                                return parent, neighbor
                        q.append(neighbor)
        return None, None

    forward_parent, forward_meet = bfs([start], is_forward=True)
    if forward_meet is not None:
        return rebuild_path(forward_parent, start, forward_meet)

    backward_parent, backward_meet = bfs([goal], is_forward=False)
    if backward_meet is None:
        return []

    while forward_meet != start:
        next_cell = backward_parent.get(forward_meet, None)
        if next_cell is None or next_cell in forward_parent:
            break
        backward_parent[forward_meet] = None
        forward_meet = forward_parent[forward_meet]

    if forward_meet == start:
        return [start]

    forward_meet = goal
    backward_meet = goal
    for key in backward_parent:
        if key in forward_parent:
            if key != start and key != goal:
                forward_meet = key
                backward_meet = key
                break

    forward_path = rebuild_path(forward_parent, start, forward_meet)
    backward_path = rebuild_path(backward_parent, backward_meet, goal)
    return forward_path[:-1] + backward_path[::-1]

def rebuild_path(parent, start, end):
    path = [end]
    while path[-1] != start:
        prev = parent[path[-1]]
        if prev is None:
            return []
        path.append(prev)
    return path[::-1]
