                pos = frontier.popleft()
                if pos in other_visited:
                    return pos
                for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                    r, c = pos
                    nr, nc = r + dr, c + dc
                    if is_forward:
