    parent_forward = {start: None}
    parent_backward = {goal: None}

    while forward_queue and backward_queue:
        meeting = bfs(forward_queue, forward_visited, backward_visited, True)
        if meeting:
            meeting_point = meeting
            break
        meeting = bfs(backward_queue, backward_visited, forward_visited, False)
        if meeting:
            meeting_point = meeting
            break

    if not meeting_point:
        return []

    # Reconstruct path forward
    path_forward = []
    curr = meeting_point
    while curr is not None:
        path_forward.append(curr)
        curr = parent_forward[curr]
    path_forward.reverse()

    # Reconstruct path backward (excluding meeting point to avoid duplication)
    path_backward = []
    curr = parent_backward[meeting_point]
    while curr is not None:
        path_backward.append(curr)
        curr = parent_backward[curr]
    path_backward.reverse()

