    def neighbors(r, c):
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if is_valid(nr, nc):
                yield nr, nc

    dist = {}
    prev = {}
    pq = [(0, start)]
    dist[start] = 0

    while pq:
        current_dist, current = heapq.heappop(pq)

        if current == goal:
            break

        if current_dist > dist.get(current, float('inf')):
            continue

        for neighbor in neighbors(*current):
            if neighbor not in dist or dist[neighbor] > current_dist + 1:
                dist[neighbor] = current_dist + 1
                prev[neighbor] = current
                heapq.heappush(pq, (dist[neighbor], neighbor))

    if goal not in prev:
        return []

    path = []
    current = goal
    while current != start:
        path.append(current)
        current = prev[current]
    path.append(start)
    path.reverse()

    return path
