    def dfs(pos, limit, visited):
        if pos == goal:
            return [pos]
        if pos in visited:
            return None
        new_visited = visited | {pos}
        h = heuristic(pos)
        if h > limit:
            return None
        for dr, dc in directions:
            r, c = pos[0] + dr, pos[1] + dc
            if 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.':
                result = dfs((r, c), limit, new_visited)
                if result is not None:
                    return [pos] + result
        return None

    # IDA* search
    def ida_star():
        limit = heuristic(start)
        path = None
        while limit <= heuristic(goal):  # heuristic(goal) is max limit we may reach
            result = dfs(start, limit, set())
            if result is not None:
                return [start] + result
            if result == 'Too deep':
                return []
            if result is None:
                new_limit = float('inf')
                for dr, dc in directions:
                    r, c = start[0] + dr, start[1] + dc
                    if 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.':
                        h = heuristic((r, c))
                        new_limit = min(new_limit, h)
                if new_limit == float('inf'):
                    return []
                limit = new_limit
            else:
                return result
        return []

    path = ida_star()
