    rows, cols = len(grid), len(grid[0])
    if (start == goal) and (grid[start[0]][start[1]] == '.'):
        return [start]

    # Check if start or goal is a wall
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def manhattan(p1, p2):
        return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

    def search(pos, g, bound, path, visited):
        f = g + manhattan(pos, goal)
        if f > bound:
            return f, path
        if pos == goal:
            return True, path + [pos]
        min_val = sys.maxsize
        for dr, dc in directions:
            nr, nc = pos[0] + dr, pos[1] + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.' and (nr, nc) not in visited:
                visited.add((nr, nc))
                new_path = path + [(nr, nc)]
                res, new_path = search((nr, nc), g + 1, bound, new_path, visited)
                if res is True:
                    return True, new_path
                if res < min_val:
                    min_val = res
                visited.remove((nr, nc))
        return min_val, []

    bound = manhattan(start, goal)
    path_found = []
    while True:
        visited = set([start])
        result, path = search(start, 0, bound, [start], visited)
        if result is True:
            path_found = path
            break
        if result == float('inf'):
            break
        bound = result
    return path_found
