import itertools

def solve(grid, start, goal):
    rows, cols = len(grid), len(grid[0])

    # Check if start or goal is a wall
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []

    # If start equals goal
    if start == goal:
        return [start]

    # Directions: up, down, left, right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def h(pos):
        # Heuristic: Manhattan distance
        return abs(pos[0] - goal[0]) + abs(pos[1] - goal[1])

    def dfs(pos, g, threshold):
        f = g + h(pos)
        if f > threshold:
            return f
        if pos == goal:
            return True
        min_cost = float('inf')
        for dr, dc in directions:
            r, c = pos[0] + dr, pos[1] + dc
            if 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.' and (r, c) != start:
                grid[r] = grid[r][:c] + '#'  # Mark as visited
                result = dfs((r, c), g + 1, threshold)
                if result is True:
                    return True
                if result < min_cost:
                    min_cost = result
                grid[r] = grid[r][:c] + '.'  # Unmark
        return min_cost

    for depth in itertools.count(h(start)):
        grid[start[0]] = grid[start[0][:start[1]] + '#' + grid[start[0]][start[1]+1:]
        result = dfs(start, 0, depth)
        grid[start[0]] = grid[start[0][:start[1]] + '.' + grid[start[0]][start[1]+1:]
        if result is True:
            break
    else:
        return []

    # Reconstruct path
    path = []
    pos = start
    for dr, dc in directions:
        r, c = pos[0] + dr, pos[1] + dc
        if 0 <= r < rows and 0 <= c < cols and grid[r][c] != '.':
            continue
        next_pos = (r, c)
        path.append(pos)
        pos = next_pos
        while True:
            found = False
            for ndr, ndc in directions:
                nr, nc = pos[0] + ndr, pos[1] + ndc
                if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] != '.':
                    pos = (nr, nc)
                    path.append(pos)
                    found = True
                    break
            if not found:
                break
    path.append(goal)
    return path
