def solve(grid, start, goal):
    from heapq import heappush, heappop

    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0

    if (
        not (0 <= start[0] < rows and 0 <= start[1] < cols)
        or not (0 <= goal[0] < rows and 0 <= goal[1] < cols)
        or grid[start[0]][start[1]] == '#'
        or grid[goal[0]][goal[1]] == '#'
    ):
        return []

    if start == goal:
        return [start]

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]  # up, down, left, right

    def heuristic(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def search(limit):
        def dfs(node, path, cost):
            if node in path:
                return None
            if node == goal:
                return path + [node]
            path = path + [node]
            for dr, dc in directions:
                r, c = node[0] + dr, node[1] + dc
                if not (0 <= r < rows and 0 <= c < cols) or grid[r][c] == '#':
                    continue
                next_node = (r, c)
                h = heuristic(next_node, goal)
                if cost + 1 + h > limit:
                    continue
                result = dfs(next_node, path, cost + 1)
                if result is not None:
                    return result
            return None

        return dfs(start, [], 0)

    def idastar():
        bound = heuristic(start, goal)
        while True:
            result = search(bound)
            if result is not None:
                return result
            if bound >= float('inf'):
                return []
            # get next bound from failed search (minimum f-cost exceeding current bound)
            bound = float('inf')
            visited = set()

            def dfs_get_bound(node, cost, goal):
                nonlocal bound
                if node == goal:
                    return cost
                h = heuristic(node, goal)
                f = cost + h
                if f > bound:
                    bound = min(bound, f)
                    return f
                for dr, dc in directions:
                    r, c = node[0] + dr, node[1] + dc
                    if (r, c) in visited or not (0 <= r < rows and 0 <= c < cols) or grid[r][c] == '#':
                        continue
                    visited.add((r, c))
                    new_cost = dfs_get_bound((r, c), cost + 1, goal)
                    if new_cost is not None:
                        return new_cost
                    bound = min(bound, new_cost)
                return None

            visited.add(start)
            bound = min(bound, dfs_get_bound(start, 0, goal))
            if bound == float('inf'):
                return []

    return idastar()
