def solve(grid, start, goal):
    from collections import deque

    if not grid or not grid[0]:
        return []

    rows = len(grid)
    cols = len(grid[0])

    def is_inside(r, c):
        return 0 <= r < rows and 0 <= c < cols

    def is_free(r, c):
        return is_inside(r, c) and grid[r][c] == '.'

    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]  # right, down, left, up
    visited = [[False] * cols for _ in range(rows)]

    def bfs(start, goal):
        queue = deque()
        queue.append(start)
        visited[start[0]][start[1]] = True
        parent = {}

        while queue:
            curr = queue.popleft()
            if curr == goal:
                break
            r, c = curr
            for dr, dc in directions:
                nr, nc = r + dr, c + dc
                if is_free(nr, nc) and not visited[nr][nc]:
                    visited[nr][nc] = True
                    parent[(nr, nc)] = curr
                    queue.append((nr, nc))

        if goal not in parent:
            return []

        path = [goal]
        while path[-1] != start:
            path.append(parent[path[-1]])
        path.reverse()
        return path

    if start == goal:
        return [start]

    if not is_free(*start) or not is_free(*goal):
        return []

    return bfs(start, goal)
