def solve(grid, start, goal):
    from collections import deque

    def is_valid(pos):
        r, c = pos
        return 0 <= r < len(grid) and 0 <= c < len(grid[0]) and grid[r][c] == '.'

    def get_neighbors(pos):
        r, c = pos
        return [
            (r - 1, c),  # up
            (r + 1, c),  # down
            (r, c - 1),  # left
            (r, c + 1)   # right
        ]

    def reconstruct_path(came_from, current):
        total_path = [current]
        while current in came_from:
            current = came_from[current]
            total_path.insert(0, current)
        return total_path

    def jps_search(grid, start, goal):
        if start == goal and is_valid(start):
            return [start]
        if not is_valid(start) or not is_valid(goal):
            return []

        open_set = set()
        closed_set = set()
        came_from = {}
        g_score = {start: 0}
        open_set.add(start)

        while open_set:
            current = min(open_set, key=lambda x: g_score[x])
            if current == goal:
                return reconstruct_path(came_from, current)

            open_set.remove(current)
            closed_set.add(current)

            for neighbor in get_neighbors(current):
                if not is_valid(neighbor) or neighbor in closed_set:
                    continue

                tentative_g = g_score[current] + 1
                if neighbor not in g_score or tentative_g < g_score[neighbor]:
                    came_from[neighbor] = current
                    g_score[neighbor] = tentative_g
                    if neighbor not in open_set:
                        open_set.add(neighbor)

        return []

    return jps_search(grid, start, goal)
