        goal[0] >= len(grid) or
        goal[1] < 0 or
        goal[1] >= len(grid[0]) or
        grid[goal[0]][goal[1]] == '#'
    ):
        return []

    def is_valid(x, y):
        return 0 <= x < len(grid) and 0 <= y < len(grid[0]) and grid[x][y] == '.'

    def manhattan(p1, p2):
        return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    diag_dir = {
        (-1, -1): 'ul',
        (-1, 1): 'ur',
        (1, -1): 'dl',
        (1, 1): 'dr',
    }

    def jump(x, y, dx, dy, parent_dx, parent_dy):
        if not is_valid(x + dx, y + dy):
            return None

        x += dx
        y += dy

        while True:
            if (x + dx, y + dy) == parent_dx or (x + dx, y + dy) == parent_dy:
                break
            if is_valid(x, y) and can_see(x, y, x - dx, y - dy, -dx, -dy, x, y):
                return (x, y)
            if is_valid(x, y) and not can_see(x - dx, x - 2*dx, y - dy, y - 2*dy, -dx, -dy, x, y):
                return (x, y)
            x += dx
            y += dy
            if not is_valid(x, y):
                return None

    def can_see(x1, y1, x2, y2, dx, dy, sx, sy):
        x, y = x1, y1
        while x != x2 or y != y2:
            x += dx
            y += dy
            if not is_valid(x, y) or (x, y) == (sx, sy) and x != x2 and y != y2:
                return False
        return True

    def jump_point_search(start, goal):
        queue = [(manhattan(start, goal), 0, start, None, None)]
        came_from = dict()
        visited = set()
        found = False
        result = []

        while queue:
            _, _, (x, y), px, py = heappop(queue)

            if (x, y) in visited:
                continue

            visited.add((x, y))

            if (x, y) == goal:
                found = True
                break

            for dx, dy in directions:
                nx, ny = x + dx, y + dy

                if is_valid(nx, ny) and (nx, ny) not in visited:
                    heappush(queue, (manhattan((nx, ny), goal) + 1, manhattan((nx, ny), goal), (nx, ny), x, y))
                    came_from[(nx, ny)] = (x, y)

            for dx, dy in directions:
                nx, ny = x + dx, y + dy

                if is_valid(nx, ny):
                    jx, jy = jump(x, y, dx, dy, px, py)
                    if jx and jy and (jx, jy) not in visited:
                        heappush(queue, (manhattan((jx, jy), goal) + 1, manhattan((jx, jy), goal), (jx, jy), x, y))
                        came_from[(jx, jy)] = (x, y)

        if not found:
            return []

        current = goal
        while current != start:
            result.append(current)
            current = came_from[current]
        result.append(start)
        result.reverse()
        return result

    return jump_point_search(start, goal)
