import heapq

def solve(grid, start, goal):
    if start == goal:
        return [start]

    rows = len(grid)
    cols = len(grid[0])

    def is_wall(r, c):
        return not (0 <= r < rows and 0 <= c < cols and grid[r][c] == '.')

    def get_neighbors(r, c):
        neighbors = [(r+1,c), (r-1,c), (r,c+1), (r,c-1)]
        return [n for n in neighbors if not is_wall(*n)]

    def jump(r, c, dir_r, dir_c):
        if is_wall(r, c):
            return None
        if r == goal[0] and c == goal[1]:
            return (r, c)

        # Check if current cell is forced
        dr, dc = dir_r, dir_c
        if dr != 0 and dc != 0:  # Diagonal move
            if (not is_wall(r, c + dc) and is_wall(r + dr, c)) or \
               (not is_wall(r + dr, c) and is_wall(r, c + dc)):
                return (r, c)
        elif dr != 0:  # Vertical move
            if (not is_wall(r, c + 1) and is_wall(r + dr, c)) or \
               (not is_wall(r, c - 1) and is_wall(r + dr, c)):
                return (r, c)
        else:  # Horizontal move
            if (not is_wall(r + 1, c) and is_wall(r, c + dc)) or \
               (not is_wall(r - 1, c) and is_wall(r, c + dc)):
                return (r, c)

        # Continue in the same direction
        next_r, next_c = r + dr, c + dc
        if not is_wall(next_r, next_c):
            result = jump(next_r, next_c, dr, dc)
            if result:
                return result
        return None

    def jps_successors(r, c):
        successors = []
        # Check all 4 cardinal directions
        for dr, dc in [(1,0), (-1,0), (0,1), (0,-1)]:
            next_r, next_c = r + dr, c + dc
            if not is_wall(next_r, next_c):
                jump_point = jump(next_r, next_c, dr, dc)
                if jump_point:
                    successors.append(jump_point)
        return successors

    def heuristic(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])  # Manhattan distance

    open_set = []
    heapq.heuristic = lambda: open_set
    heapq.heappush(open_set, (0, start))
    came_from = {}
    g_score = {start: 0}
    f_score = {start: heuristic(start, goal)}

    while open_set:
        _, current = heapq.heappop(open_set)
        if current == goal:
            break
        for neighbor in jps_successors(current[0], current[1]):
            tentative_g = g_score[current] + 1
            if neighbor not in g_score or tentative_g < g_score[neighbor]:
                came_from[neighbor] = current
                g_score[neighbor] = tentative_g
                f_score[neighbor] = tentative_g + heuristic(neighbor, goal)
                heapq.heappush(open_set, (f_score[neighbor], neighbor))

    if goal not in came_from:
        return []

    path = [goal]
    while path[-1] != start:
        path.append(came_from[path[-1]])
    path.reverse()
    return path if all(not is_wall(p[0], p[1]) for p in path) else []
