            if grid[nx][ny] == '.':
                return (x, y)
            for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                if dx != -dirx or dy != -diry:
                    if is_valid(px + dx, py + dy):
                        return (x, y)
            return jump(x + dirx, y + diry, dirx, diry)
        return None

