import heapq

def solve(grid, start, goal):
    if start == goal:
        return [start]

    rows = len(grid)
    cols = len(grid[0])

    if not (0 <= start[0] < rows and 0 <= start[1] < cols) or grid[start[0]][start[1]] == '#':
        return []
    if not (0 <= goal[0] < rows and 0 <= goal[1] < cols) or grid[goal[0]][goal[1]] == '#':
        return []

    def neighbors(r, c):
        directions = [(-1,0), (1,0), (0,-1), (0,1)]  # Up, Down, Left, Right
        res = []
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.':
                res.append((nr, nc))
        return res

    def is_corner(r, c, prev_dr, prev_dc):
        dirs = [(-1,0), (1,0), (0,-1), (0,1)]
        if grid[r][c] == '#':
            return False
        for dr, dc in dirs:
            if dr != -prev_dr or dc != -prev_dc:
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.':
                    if (nr - r) * prev_dr + (nc - c) * prev_dc != 0:
                        return True
        return False

    def jump(r, c, dir_r, dir_c):
        if grid[r][c] == '#':
            return None
        if r == goal[0] and c == goal[1]:
            return (r, c)
        # Check for forced neighbors
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            if dr != -dir_r or dc != -dir_c:
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.':
                    if dr == 0 or dc == 0:
                        if (dr != 0 and dc != 0) and (nr - r) * dir_r + (nc - c) * dir_c != 0:
                            if not (0 <= r + dir_r < rows and 0 <= c + dir_c < cols and grid[r+dir_r][c+dir_c] == '.'):
                                return (r, c)
                    if (dr == dir_r and dc == dir_c) or (dr == 0 and dc == 0):
                        continue
                    if grid[nr][nc] == '.' and (is_corner(r, c, dir_r, dir_c)):
                        return (r, c)
        # Recursive jump in the direction
        nr, nc = r + dir_r, c + dir_c
        if not (0 <= nr < rows and 0 <= nc < cols):
            return None
        if grid[nr][nc] == '#':
            return None
        res = jump(nr, nc, dir_r, dir_c)
        return res if res else None

    def get_jps_neighbors(r, c):
        neighbors_list = []
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.':
                jpt = jump(nr, nc, dr, dc)
                if jpt:
                    neighbors_list.append(jpt)
        return neighbors_list

    open_set = [(0, start[0], start[1])]
    came_from = {}
    g_score = {start: 0}
    f_score = {start: manhattan(start, goal)}

    def manhattan(p1, p2):
        return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

    while open_set:
        _, r, c = heapq.heappop(open_set)
        current = (r, c)
        if current == goal:
            return reconstruct_path(came_from, current)

        for j in get_jps_neighbors(r, c):
            if j in came_from or grid[j[0]][j[1]] == '#':
                continue
            tentative_g_score = g_score[current] + 1
            if j not in g_score or tentative_g_score < g_score[j]:
                came_from[j] = current
                g_score[j] = tentative_g_score
                f_score[j] = g_score[j] + manhattan(j, goal)
                heapq.heappush(open_set, (f_score[j], j[0], j[1]))

    return []

def reconstruct_path(came_from, current):
    path = [current]
    while current in came_from:
        current = came_from[current]
        path.insert(0, current)
    return path
