def solve(grid, start, goal):
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []

    if start == goal:
        return [start]

    def is_valid(r, c):
        return 0 <= r < len(grid) and 0 <= c < len(grid[0]) and grid[r][c] == '.'

    def jps_pcost(r1, c1, r2, c2):
        return abs(r1 - r2) + abs(c1 - c2)

    from collections import deque

    def jps_jump(r, c, dr, dc, goal):
        if (r, c) == goal:
            return (r, c)
        if not is_valid(r, c):
            return None
        result = None

        if dr != 0:
            for dc_step in [-1, 0, 1]:
                if dc_step != 0 and (dr, dc_step) != (0, 1) and (dr, dc_step) != (0, -1):
                    nr, nc = r + dr, c + dc_step
                    if is_valid(nr, nc):
                        result = (nr, nc)
                if dc != 0:
                    nr, nc = r + dr, c + dc
                    if is_valid(nr, nc):
                        result = (nr, nc)
        elif dc != 0:
            for dr_step in [-1, 0, 1]:
                if dr_step != 0 and (dr_step, dc) != (1, 0) and (dr_step, dc) != (-1, 0):
                    nr, nc = r + dr_step, c + dc
                    if is_valid(nr, nc):
                        result = (nr, nc)
                if dr != 0:
                    nr, nc = r + dr, c + dc
                    if is_valid(nr, nc):
                        result = (nr, nc)

        if result:
            return jps_jump(result[0], result[1], dr, dc, goal)
        return None

    def heuristic(r1, c1, r2, c2):
        return abs(r1 - r2) + abs(c1 - c2)

    open_set = []
    closed_set = set()
    parent_map = {}

    from heapq import heappush, heappop

    g = {start: 0}
    f = {start: jps_pcost(*start, *goal)}
    heappush(open_set, (f[start], start))

    while open_set:
        _, node = heappop(open_set)
        if node == goal:
            path = []
            while node:
                path.append(node)
                node = parent_map.get(node)
            return path[::-1]

        closed_set.add(node)
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            next_node = jps_jump(node[0], node[1], dx, dy, goal)
            if next_node is not None:
                if next_node not in closed_set and is_valid(*next_node):
                    tentative_g = g[node] + jps_pcost(node[0], node[1], next_node[0], next_node[1])
                    if tentative_g < g.get(next_node, float('inf')):
                        parent_map[next_node] = node
                        g[next_node] = tentative_g
                        f[next_node] = tentative_g + heuristic(next_node[0], next_node[1], goal[0], goal[1])
                        heappush(open_set, (f[next_node], next_node))

    return []
