        2: (0, -1),  # Left
        3: (-1, 0),  # Up
        4: (0, 1),   # Right (no diagonal)
        5: (1, 0),   # Down
        6: (0, -1),  # Left
        7: (-1, 0)   # Up
    }

    def get_neighbors(point):
        r, c = point
        neighbors = []
        for dr, dc in [(0, 1), (1, 0), (0, -1), (-1, 0)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]) and grid[nr][nc] == '.':
                neighbors.append((nr, nc))
        return neighbors

    def is_walkable(x, y):
        return 0 <= x < len(grid) and 0 <= y < len(grid[0]) and grid[x][y] == '.'

    def jump_point_search(start, goal):
        open_set = []
        came_from = {}
        g_score = {start: 0}
        f_score = {start: heuristic(start, goal)}
        heapq.heappush(open_set, (f_score[start], start))

        def heuristic(a, b):
            return abs(a[0] - b[0]) + abs(a[1] - b[1])

        def prune_neighbors(current, parent_dir):
            pruned = []
            r, c = current
            dr, dc = dir_map[parent_dir]
            for i in [0, 2 if parent_dir % 2 == 0 else 1, 4, 5, 6, 7]:
                ndr, ndc = dir_map[i]
                nr, nc = r + ndr, c + ndc
                if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]) and grid[nr][nc] == '.':
                    pruned.append((nr, nc))
            return pruned

        while open_set:
            _, current = heapq.heappop(open_set)
            if current == goal:
                return reconstruct_path(came_from, current)

            for neighbor in prune_neighbors(current, -1):
                tentative_g = g_score[current] + 1
                if neighbor not in g_score or tentative_g < g_score[neighbor]:
                    came_from[neighbor] = current
                    g_score[neighbor] = tentative_g
                    f_score[neighbor] = tentative_g + heuristic(neighbor, goal)
                    heapq.heappush(open_set, (f_score[neighbor], neighbor))

        return []

    def reconstruct_path(came_from, current):
        path = [current]
        while current in came_from:
            current = came_from[current]
            path.insert(0, current)
        return path

    return jump_point_search(start, goal)
