    dir_names = ['up', 'down', 'left', 'right']
    opp_dir = {'up': 'down', 'down': 'up', 'left': 'right', 'right': 'left'}

    def get_dir(from_pos, to_pos):
        dr, dc = to_pos[0] - from_pos[0], to_pos[1] - from_pos[1]
        for i, (drow, dcol) in enumerate(dirs):
            if drow == dr and dcol == dc:
                return dir_names[i]
        return None

    def manhattan(p1, p2):
        return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

    class Node:
        def __init__(self, pos):
            self.pos = pos
            self.parent = None
            self.dir = None
            self.children = set()

    def get_neighbors(pos, dir=None, pruned=False):
        r, c = pos
        neighbors = []
        for dr, dc, ddir in zip(dirs, ['up', 'down', 'left', 'right']):
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.':
                if pruned and dir is not None and dir != ddir and dir is not None and ddir != opp_dir[dir]:
                    continue
                neighbors.append((nr, nc))
        return neighbors

    def jps_search(start, goal):
        def heuristic(pos):
            return manhattan(pos, goal)
        open_set = []
        closed = set()
        came_from = {}
        g_score = {start: 0}
        f_score = {start: heuristic(start)}
        heapq.heappush(open_set, (f_score[start], start))
        while open_set:
            _, current = heapq.heappop(open_set)
            if current == goal:
                return reconstruct_path(came_from, current)
            closed.add(current)
            for next in get_neighbors(current):
                if next in closed:
                    continue
                g = g_score[current] + 1
                if next not in g_score or g < g_score[next]:
                    came_from[next] = current
                    g_score[next] = g
                    f_score[next] = g + heuristic(next)
                    heapq.heappush(open_set, (f_score[next], next))
        return None

    def reconstruct_path(came_from, current):
        path = [current]
        while current in came_from:
            current = came_from[current]
            path.append(current)
        return list(reversed(path))

    path = jps_search(start, goal)
    if path and path[0] == start and path[-1] == goal:
        return path
    return []
