        return [(nr, nc) for nr, nc in [(r-1,c), (r+1,c), (r,c-1), (r,c+1)] if is_valid((nr, nc))]

    def heuristic(pos, end):
        r1, c1 = pos
        r2, c2 = end
        return abs(r1 - r2) + abs(c1 - c2)

    def a_star_search(start, goal, get_neighbors_func, heuristic_func):
        frontier = []
        heapq.heappush(frontier, (0, start))
        came_from = {}
        cost_so_far = {}
        came_from[start] = None
        cost_so_far[start] = 0

        while frontier:
            _, current = heapq.heappop(frontier)

            if current == goal:
                break

            for next_pos in get_neighbors_func(current):
                new_cost = cost_so_far[current] + 1
                if next_pos not in cost_so_far or new_cost < cost_so_far[next_pos]:
                    cost_so_far[next_pos] = new_cost
                    priority = new_cost + heuristic_func(next_pos, goal)
                    heapq.heappush(frontier, (priority, next_pos))
                    came_from[next_pos] = current

        return came_from

    forward_path = a_star_search(start, goal, get_neighbors, heuristic)
    if goal not in forward_path:
        return []

    reverse_path = a_star_search(goal, start, get_neighbors, heuristic)
    if start not in reverse_path:
        return []

    def reconstruct_path(f_path, r_path):
        def to_list(path, start, end):
            result = []
            current = end
            while current != start:
                result.append(current)
                current = path[current]
            result.append(start)
            return result[::-1]

        f_path_list = to_list(f_path, start, goal)
        r_path_list = to_list(reverse_path, goal, start)

        for i in range(1, min(len(f_path_list), len(r_path_list))):
            if f_path_list[i] == r_path_list[i]:
                return f_path_list[:i+1] + r_path_list[i+1:][::-1]

        return f_path_list

    return reconstruct_path(forward_path, reverse_path)
