    rows = len(grid)
    cols = len(grid[0])

    if (
        not (0 <= start[0] < rows and 0 <= start[1] < cols and grid[start[0]][start[1]] == '.')
        or not (0 <= goal[0] < rows and 0 <= goal[1] < cols and grid[goal[0]][goal[1]] == '.')
    ):
        return []

    DIRS = [(-1, 0), (0, 1), (1, 0), (0, -1)]  # up, right, down, left

    def is_in_bounds(r, c):
        return 0 <= r < rows and 0 <= c < cols

    def is_wall(r, c):
        return not (is_in_bounds(r, c) and grid[r][c] == '.')

    def get_neighbors(r, c, dir_index):
        neighbors = []
        dr, dc = DIRS[dir_index]
        tr, tc = r + dr, c + dc
        extend = [0]
        while is_in_bounds(tr, tc) and grid[tr][tc] == '.':
            if (tr, tc) == goal:
                extend.append(1)
            tr += dr
            tc += dc
        if extend[0] > 0:
            neighbors.append((r + dr * extend[0], c + dc * extend[0]))
        # Check for diagonal jump in JPS style
        if dir_index in (0, 1):  # up or right
            for d in [(1, -1), (1, 1), (-1, -1), (-1, 1)]:
                nr, nc = r + d[0], c + d[1]
                if is_in_bounds(nr, nc) and grid[nr][nc] == '.' and not is_wall(nr + dr, nc + dc):
                    neighbors.append((nr, nc))
        return neighbors

    def forced_neighbors(r, c, dir_index):
        dr, dc = DIRS[dir_index]
        ndr, ndc = -dr, -dc
        tr, tc = r + dr, c + dc
        if not is_wall(tr, tc):
            if dir_index in (0, 2):  # up or down
                # Check for forced neighbors left and right
                for ndir in [(-1, 0), (1, 0)]:
                    ntr, ntc = tr + ndir[0] + ndr, tc + ndir[1] + ndc
                    if not is_wall(ntr, ntc):  # The path can continue beyond
                        return True
            elif dir_index in (1, 3):  # right or left
                # Check for forced neighbors up and down
                for ndir in [(0, -1), (0, 1)]:
                    ntr, ntc = tr + ndir[0] + ndr, tc + ndir[1] + ndc
                    if not is_wall(ntr, ntc):  # The path can continue beyond
                        return True
            return False
        return True

    def jump(r, c, dir_index, parent_dir):
        dr, dc = DIRS[dir_index]
        tr, tc = r + dr, c + dc
        if not is_in_bounds(tr, tc) or is_wall(tr, tc):
            return None
        if (tr, tc) == goal:
            return (tr, tc)
        # Check for forced neighbors
        if forced_neighbors(r, c, dir_index):
            return (tr, tc)
        # Continue straight if no forced neighbors
        next_jump = jump(tr, tc, dir_index, dir_index)
        if next_jump:
            return next_jump
        # Check for diagonals
        d1, d2 = None, None
        for new_dir in range(4):
            if DIRS[new_dir] != DIRS[dir_index] and (new_dir != parent_dir):
                if (dir_index in (0, 2) and new_dir in (1, 3)) or (dir_index in (1, 3) and new_dir in (0, 2)):
                    j = jump(tr, tc, new_dir, dir_index)
                    if j:
                        return j
        return None

    def neighbors(r, c, parent_dir):
        res = []
        for dir_index in range(4):
            if dir_index != parent_dir:
                jump_result = jump(r, c, dir_index, parent_dir)
                if jump_result:
                    res.append(jump_result)
        return res

    def heuristic(r1, c1, r2, c2):
        return abs(r1 - r2) + abs(c1 - c2)

    def reconstruct_path(came_from, current):
        path = [current]
        while current in came_from:
            current = came_from[current]
            path.append(current)
        path.reverse()
        return path

    open_set = []
    heapq.heuristic_push(open_set, (heuristic(*start, *goal), 0, start))
    came_from = {}
    g_score = {start: 0}
    f_score = {start: heuristic(*start, *goal)}

    while open_set:
        current = heapq.heuristic_pop(open_set)[2]

        if current == goal:
            return reconstruct_path(came_from, current)

        for next_cell in neighbors(*current, -1):
            nr, nc = next_cell
            if is_wall(nr, nc):
                continue
            tentative_g = g_score[current] + 1
            if (nr, nc) not in g_score or tentative_g < g_score[(nr, nc)]:
                came_from[(nr, nc)] = current
                g_score[(nr, nc)] = tentative_g
                f_score[(nr, nc)] = tentative_g + heuristic(nr, nc, *goal)
                heapq.heuristic_push(open_set, (f_score[(nr, nc)], g_score[(nr, nc)], (nr, nc)))

    return []
