def solve(grid, start, goal):
    def get_neighbors(pos):
        r, c = pos
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]) and grid[nr][nc] == '.':
                yield (nr, nc)

    def h(pos):
        return abs(pos[0] - target) + abs(pos[1] - target)

    if start == goal:
        return [start]

    startrow, startcol = start
    goalrow, goalcol = goal

    if grid[startrow][startcol] == '#' or grid[goalrow][goalcol] == '#':
        return []

    target = goalcol if startcol == goalcol else goalrow

    forward = {start: None}
    backward = {goal: None}
    f_open = [(0, start)]
    b_open = [(0, goal)]

    def expand(fwd, rev, frontier, is_forward):
        cost, cur = heappop(frontier)
        if cur in (rev if is_forward else fwd).keys():
            path = reconstruct(fwd, rev, cur)
            if path:
                return path
        for n in get_neighbors(cur):
            if n not in (rev if is_forward else fwd) and n not in [x[1] for x in frontier]:
                (fwd if is_forward else rev)[n] = cur
                heappush(frontier, (cost + 1, n))
        return None

    def reconstruct(fwd, rev, meet):
        path = [meet]
        cur = meet
        while cur in rev and rev[cur] is not None:
            path.append(rev[cur])
            cur = rev[cur]
        path.reverse()
        cur = path[-1]
        while cur in fwd and fwd[cur] is not None:
            path.append(fwd[cur])
            cur = fwd[cur]
        path.append(start)
        path.reverse()
        return path if path[0] == goal and path[-1] == start else None

    while f_open and b_open:
        path = expand(forward, backward, f_open, True)
        if path: return path
        path = expand(backward, forward, b_open, False)
        if path: return path

    return []
