                        heapq.heappush(queue, (heuristic((nr, nc)) + len(visited), (nr, nc)))
                        came_from[(nr, nc)] = current
        return None

    path_start = [(0, start, goal)]
    path_goal = [(0, goal, start)]

    def start_to_goal(node):
        return node == goal

    def goal_to_start(node):
        return node == start

