    def is_free(r, c):
        return 0 <= r < len(grid) and 0 <= c < len(grid[0]) and grid[r][c] == '.'

    def get_neighbors(r, c):
        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
        return [(r + dr, c + dc) for dr, dc in directions if is_free(r + dr, c + dc)]

    def a_star(start, goal, get_neighbors_func):
        h = lambda a, b: abs(a[0] - b[0]) + abs(a[1] - b[1])
        open_set = [(h(*start, *goal), start)]
        came_from = {}
        cost_so_far = {start: 0}
        while open_set:
            _, current = heapq.heappop(open_set)
            if current == goal:
                break
            for neighbor in get_neighbors_func(*current):
                new_cost = cost_so_far[current] + 1
                if neighbor not in cost_so_far or new_cost < cost_so_far[neighbor]:
                    cost_so_far[neighbor] = new_cost
                    priority = new_cost + h(*neighbor, *goal)
                    heapq.heappush(open_set, (priority, neighbor))
                    came_from[neighbor] = current

        if goal not in came_from:
            return []

        path = [goal]
        while path[-1] != start:
            path.append(came_from[path[-1]])
        return path[::-1]

    if start == goal:
        return [start] if is_free(*start) else []

    f1 = a_star(start, goal, get_neighbors)
    f2 = a_star(goal, start, get_neighbors)

    common = set(f1) & set(f2)
    if not common:
        return []
    common = sorted(common, key=lambda x: f1.index(x))

    i = f1.index(common[0])
    j = f2.index(common[0])
    return f1[:i+1] + f2[j+1:][::-1]
