        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def estimate(frontier, goal_set):
        min_h = float('inf')
        for pos in frontier:
            for g in goal_set:
                d = heuristic(pos, g)
                if d < min_h:
                    min_h = d
        return min_h

    def get_open(frontier_set, came_from, g, other_g, h):
        for pos in frontier_set:
            f = g[pos] + h(pos, goal) if h else other_g[pos]
            yield (f, pos, g[pos])

    def reverse_path(came_from_start, came_from_goal, meet):
        path_start = []
        cur = meet
        while cur in came_from_start:
            path_start.append(cur)
            cur = came_from_start[cur]
        path_goal = []
        cur = meet
        while cur in came_from_goal:
            path_goal.append(cur)
            cur = came_from_goal[cur]
        path = path_start[::-1] + path_goal
        return path

