    open_goal = [(g_from_goal[goal] + h(goal, start), goal)]
    came_from_start = {start: None}
    came_from_goal = {goal: None}
    frontier_start = set([start])
    frontier_goal = set([goal])

    while open_start and open_goal:
        open_start = sorted(open_start)
        open_goal = sorted(open_goal)

        if open_start and open_goal and estimate(frontier_start, frontier_goal) > len(open_start) + len(open_goal):
            break

        if open_start[0][0] <= open_goal[0][0]:
