                    g_from_start[neighbor] = g_from_start[pos] + 1
                    came_from_start[neighbor] = pos
                    open_start.append((g_from_start[neighbor] + h(neighbor, goal), neighbor))
                    frontier_start.add(neighbor)
        else:
            _, pos = open_goal.pop(0)
            if pos in came_from_start:
                return reverse_path(came_from_start, came_from_goal, pos)
            frontier_goal.remove(pos)
            for neighbor in neighbors(pos):
