        path2 = a_star(backward_start, backward_goal, get_neighbors)
        if path1 is None and path2 is None:
            return []
        if path1 is not None:
            path = path1
            break
        if path2 is not None:
            path = path2[::-1]
            break

    # Filtering out nodes that are not on the path
    visited_forward = set()
    q = deque()
    q.append(start)
    prev_forward = {start: None}
    while q:
        pos = q.popleft()
        if pos == goal:
            break
        for neighbor in get_neighbors(pos):
            if neighbor not in visited_forward:
                visited_forward.add(neighbor)
                prev_forward[neighbor] = pos
                q.append(neighbor)

    visited_backward = set()
    q = deque()
    q.append(goal)
    prev_backward = {goal: None}
    while q:
        pos = q.popleft()
        if pos == start:
            break
        for neighbor in get_neighbors(pos):
            if neighbor not in visited_backward:
                visited_backward.add(neighbor)
                prev_backward[neighbor] = pos
                q.append(neighbor)

    combined_path = [start]
    while combined_path[-1] != goal:
        current = combined_path[-1]
        for x in [current[0]-1, current[0]+1, current[0]], [current[1]-1, current[1]+1, current[1]]:
            for nr, nc in zip([current[0]-1, current[0]+1, current[0]], [current[1], current[1], current[1]-1, current[1]+1]):
                if 0 <= nr < rows and 0 <= nc < cols:
                    next_pos = (nr, nc)
                    if next_pos in prev_forward or next_pos in prev_backward:
                        if next_pos in visited_forward and next_pos in visited_backward:
                            combined_path.append(next_pos)
                            break
            else:
                continue
            break
    return combined_path
