import heapq

def solve(grid, start, goal):
    if not (0 <= start[0] < len(grid) and 0 <= start[1] < len(grid[0])):
        return []
    if not (0 <= goal[0] < len(grid) and 0 <= goal[1] < len(grid[0])):
        return []
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []
    if start == goal:
        return [start]

    rows, cols = len(grid), len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def heuristic(pos):
        return abs(pos[0] - goal[0]) + abs(pos[1] - goal[1])

    def a_star(start, goal, reverse):
        open_set = []
        heapq.heappush(open_set, (heuristic(start), start))
        came_from = {}
        g_score = {start: 0}
        f_score = {start: heuristic(start)}

        while open_set:
            current = heapq.heappop(open_set)[1]
            if current == goal:
                path = []
                while current:
                    path.append(current)
                    current = came_from.get(current)
                return path[::-1]
            for dr, dc in directions:
                nr, nc = current[0] + dr, current[1] + dc
                if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.':
                    neighbor = (nr, nc)
                    tentative_g = g_score[current] + 1
                    if neighbor not in g_score or tentative_g < g_score[neighbor]:
                        came_from[neighbor] = current
                        g_score[neighbor] = tentative_g
                        h = heuristic(neighbor)
                        f_score[neighbor] = tentative_g + h
                        heapq.heappush(open_set, (f_score[neighbor], neighbor))
        return None

    def reverse_path(path):
        return [(r, c) for c, r in path] if path else None

    # Forward from start to goal
    forward_path = a_star(start, goal, False)
    if forward_path:
        return forward_path

    # Backward from goal to start
    backward_path = a_star(goal, start, True)
    if backward_path:
        return reverse_path(backward_path)

    # Bidirectional A* with meet-in-the-middle
    forward_open = [(heuristic(start), start)]
    backward_open = [(heuristic(goal), goal)]
    forward_closed = {start: None}
    backward_closed = {goal: None}
    forward_g = {start: 0}
    backward_g = {goal: 0}
    dirs = [(0, 1), (1, 0), (0, -1), (-1, 0)]  # for consistent ordering

    def expand(state, is_forward, heuristic_func):
        g = (forward_g if is_forward else backward_g)
        _open = (forward_open if is_forward else backward_open)
        _closed = (forward_closed if is_forward else backward_closed)
        goal_state = (goal if is_forward else start)
        came_from = (forward_closed if is_forward else backward_closed)
        while _open:
            _, node = heapq.heappop(_open)
            if node in _closed:
                continue
            _closed[node] = None
            if node == goal_state:
                return node
            for dr, dc in directions:
                nr, nc = node[0] + dr, node[1] + dc
                if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.':
                    child = (nr, nc)
                    if child not in g or forward_g.get(child, float('inf')) > forward_g[node] + 1:
                        new_g = g[node] + 1
                        if is_forward:
                            forward_g[child] = new_g
                        else:
                            backward_g[child] = new_g
                        h = heuristic_func(child)
                        heapq.heappush(_open, (new_g + h, child))
        return None

    while forward_open and backward_open:
        result = expand(forward_open, True, heuristic)
        if result in backward_closed:
            # Find common node
            common = result
            # Build backward path
            backward_path = [common]
            node = common
            while backward_closed[node] is not None:
                backward_path.append(backward_closed[node])
                node = backward_closed[node]
            backward_path.reverse()
            # Build forward path
            forward_path = [common]
            node = common
            while forward_closed[node] is not None:
                forward_path.append(forward_closed[node])
                node = forward_closed[node]
            forward_path.reverse()
            return forward_path + backward_path[1:]
        result = expand(backward_open, False, heuristic)
        if result in forward_closed:
            common = result
            # Build forward path
            forward_path = [common]
            node = common
            while forward_closed[node] is not None:
                forward_path.append(forward_closed[node])
                node = forward_closed[node]
            forward_path.reverse()
