    def a_star(start, goal):
        open_set = [(0, start)]
        came_from = {}
        g_score = {start: 0}
        f_score = {start: heuristic(start, goal)}
        visited = set()
        while open_set:
            _, current = heapq.heappop(open_set)
            if current == goal:
                path = []
                while current in came_from:
                    path.append(current)
                    current = came_from[current]
                path.reverse()
                return path
            if current in visited:
                continue
            visited.add(current)
            for dr, dc in directions:
                r, c = current[0] + dr, current[1] + dc
                if (
                    0 <= r < len(grid)
                    and 0 <= c < len(grid[0])
                    and grid[r][c] == "."
                ):
                    neighbor = (r, c)
                    tentative_g = g_score[current] + 1
                    if neighbor not in g_score or tentative_g < g_score[neighbor]:
                        came_from[neighbor] = current
                        g_score[neighbor] = tentative_g
                        f_score[neighbor] = tentative_g + heuristic(neighbor, goal)
                        heapq.heappush(open_set, (f_score[neighbor], neighbor))
        return None

    path1 = a_star(start, goal)
    if path1:
        return [start] + path1

    def bidir_a_star():
        forward_queue = [(0, start)]
        backward_queue = [(0, goal)]
        forward_path = {start: None}
        backward_path = {goal: None}
        forward_g = {start: 0}
        backward_g = {goal: 0}
        forward_visit = set([start])
        backward_visit = set([goal])
        while forward_queue and backward_queue:
            if not forward_queue:
                return None
            if not backward_queue:
                return None

            for is_forward in [True, False]:
                if is_forward and not forward_queue:
                    break
                if not is_forward and not backward_queue:
                    break

                if is_forward:
                    _, current = heapq.heappop(forward_queue)
                    frontier = start
                    expand = goal
                    path = forward_path
                    g = forward_g
                    other_visit = backward_visit
                    other_path = backward_path
                    other_start = goal
                else:
                    _, current = heapq.heappop(backward_queue)
                    frontier = goal
                    expand = start
                    path = backward_path
                    g = backward_g
                    other_visit = forward_visit
                    other_path = forward_path
                    other_start = start

                if current in other_visit:
                    full_path = []
                    node1 = current
                    node2 = current
                    while node1:
                        full_path.append(node1)
                        node1 = path.get(node1)
                    while node2:
                        if node1 == node2:
                            break
                        full_path = [node2] + full_path
                        node2 = other_path.get(node2)
                    full_path.reverse()
                    return full_path

                for dr, dc in directions:
                    r, c = current[0] + dr, current[1] + dc
                    if (
                        0 <= r < len(grid)
                        and 0 <= c < len(grid[0])
                        and grid[r][c] == "."
                        and (r, c) not in path
                    ):
                        n = (r, c)
                        tentative_g = g[current] + 1
                        cost = 1
                        new_g = tentative_g + cost
                        if (r, c) not in g or new_g < g[(r, c)]:
