        queue = deque([start])
        visited[start] = True

        while queue:
            r, c = queue.popleft()
            if (r, c) == goal:
                break
            for dr, dc in directions:
                nr, nc = r + dr, c + dc
                if (
                    0 <= nr < rows and 0 <= nc < cols and
                    grid[nr][nc] == '.' and
                    (nr, nc) not in visited
                ):
                    visited[(nr, nc)] = True
                    parent[(nr, nc)] = (r, c)
                    queue.append((nr, nc))
        return parent

    visited_start = {start: True}
    parent_from_start = bfs(start, goal, visited_start)

    visited_goal = {goal: True}
    parent_from_goal = bfs(goal, start, visited_goal)

    common = set(visited_start.keys()) & set(visited_goal.keys())
    if not common:
        return []

    path = None
    for point in common:
        path_start = [goal]
        path_goal = [start]
        r, c = point
        while (r, c) != start:
            r, c = parent_from_start[(r, c)]
            path_start.append((r, c))
        r, c = point
        while (r, c) != goal:
            r, c = parent_from_goal[(r, c)]
            path_goal.append((r, c))
        combined_path = path_start + path_goal[::-1][1:]
        if combined_path[0] == start and combined_path[-1] == goal:
            path = combined_path
            break

    if path:
        for r, c in path:
            if grid[r][c] == '#':
