                path.append(curr)
                break
            path.append(curr)
            curr = front_prev[curr]
        path.reverse()
        curr = last_other
        while curr in other_prev:
            path.append(other_prev[curr])
            curr = other_prev[curr]
        return path if path[0] == start and path[-1] == goal else []

