        # Search from start
        path1 = []
        for _ in range(len(queue1)):
            pos, path = queue1.popleft()
            if pos in visited2:
                return path + list(reversed(next(p for p, path2 in queue2 if p == pos)[1:]))[::-1]
            for neighbor in get_neighbors(pos):
                if neighbor not in visited1:
                    visited1.add(neighbor)
                    queue1.append((neighbor, path + [neighbor]))

        # Search from goal
        path2 = []
        for _ in range(len(queue2)):
            pos, path = queue2.popleft()
            if pos in visited1:
                return list(reversed(path[:path.index(pos)+1])) + list(reversed(path2[:path.index(pos)+1]))[::-1]
