from collections import deque

def solve(grid, start, goal):
    if start == goal:
        return [start]

    if not (0 <= start[0] < len(grid) and 0 <= start[1] < len(grid[0])) or grid[start[0]][start[1]] == '#':
        return []
    if not (0 <= goal[0] < len(grid) and 0 <= goal[1] < len(grid[0])) or grid[goal[0]][goal[1]] == '#':
        return []

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def bfs(starts, is_reversed):
        queue = deque()
        visited = {}
        for s in starts:
            queue.append(s)
            visited[s] = None
        while queue:
            current = queue.popleft()
            for dr, dc in directions:
                nr, nc = current[0] + dr, current[1] + dc
                neighbor = (nr, nc)
                if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]) and grid[nr][nc] == '.' and neighbor not in visited:
                    visited[neighbor] = current
                    queue.append(neighbor)
                    # Early exit if we reach from the other side
                    if is_reversed and neighbor == start:
                        return visited
                    if not is_reversed and neighbor == goal:
                        return visited
        return visited

    forward_visited = bfs([start], False)
    if goal in forward_visited:
        return reconstruct_path(start, goal, forward_visited)

    backward_visited = bfs([goal], True)
    if start in backward_visited:
        return reconstruct_path(start, goal, backward_visited)

    # Check for intersection between forward and backward searches
    for _ in range(100):  # Limit iterations to prevent infinite loop (the grid is up to 30x30)
        intersection = set(forward_visited.keys()).intersection(backward_visited.keys())
        if intersection:
            meet_point = intersection.pop()
            path1 = reconstruct_path(start, meet_point, forward_visited)
            path2 = reconstruct_path(goal, meet_point, backward_visited)
            path2.reverse()
            return path1 + path2[1:]

        next_forward = [n for n in forward_visited if n not in backward_visited and grid[n[0]][n[1]] == '.']
        if not next_forward:
            return []
        forward_visited = bfs(next_forward, False)
        if goal in forward_visited:
            return reconstruct_path(start, goal, forward_visited)

        next_backward = [n for n in backward_visited if n not in forward_visited and grid[n[0]][n[1]] == '.']
        if not next_backward:
            return []
        backward_visited = bfs(next_backward, True)
        if start in backward_visited:
            return reconstruct_path(start, goal, backward_visited)

    return []

def reconstruct_path(start, goal, visited):
    path = []
    current = goal
    while current:
        path.append(current)
        current = visited[current]
    path.reverse()
    if path and path[0] != start:
        path.insert(0, start)
    return path
