                    queue.append((nr, nc, new_path))
                    visited[(nr, nc)] = (r, c)
                    if (nr, nc) == goal:
                        return path + [(r, c), (nr, nc)]
                    if (nr, nc) in forward_visited or (nr, nc) in reverse_visited:
                        # Found a meeting point
                        if is_reverse:
                            full_path = new_path + [(nr, nc)]
                            current = (nr, nc)
                            while current in forward_visited:
                                full_path.append(current)
                                r, c = current
                                current = forward_visited[(r, c)]
                            return full_path
                        else:
                            full_path = reverse_paths[(nr, nc)] + [(nr, nc)]
                            current = (nr, nc)
                            while current in reverse_visited:
                                r, c = current
                                full_path.append(reverse_visited[(r, c)])
                                current = reverse_visited[(r, c)]
                            return full_path
        return None

    if start == goal:
        if is_valid(*start):
            return [start]
        return []

