                if (nr, nc) in reverse_visited:
                    f_line = new_path + [(nr, nc)]
                    r_line = reverse_paths[(nr, nc)]
                    full_line = f_line + r_line[::-1][1:]
                    return full_line

        gr, gc, gpath = reverse_queue.popleft()
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
