        return []

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    rows, cols = len(grid), len(grid[0])

    def bfs(frontier, visited, other_visited, is_front):
        while frontier:
            level = {}
            for _ in range(len(frontier)):
                cur = frontier.popleft()
                if cur in other_visited:
                    path = []
                    if is_front:
                        path.extend(other_visited[cur])
                        path.reverse()
                        path.append(cur[0])
                    else:
                        path.append(cur[0])
                        path.extend(other_visited[cur])
                    return path
                for dr, dc in directions:
                    nr, nc = cur[0] + dr, cur[1] + dc
                    if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.':
                        neighbor = (nr, nc)
                        if neighbor not in visited:
                            visited[neighbor] = visited[cur] + [cur]
                            frontier.append(neighbor)
                            level[neighbor] = visited[neighbor] + [neighbor]
            if is_front:
                for node in level:
                    if node in other_visited:
                        return level[node] + other_visited[node]
                for node in level:
                    other_visited[node] = level[node]
            else:
                for node in level:
                    if node in other_visited:
                        other_visited[node] += level[node]
                        return other_visited[node]
                for node in level:
                    other_visited[node] = level[node]
            return None
        return []

    forward_queue = deque([(start, [start])])
    backward_queue = deque([(goal, [goal])])
    forward_visited = {start: []}
    backward_visited = {goal: []}

    result = None
    while forward_queue and backward_queue:
        result = bfs(forward_queue, forward_visited, backward_visited, True)
        if result is not None:
            return result
        result = bfs(backward_queue, backward_visited, forward_visited, False)
        if result is not None:
