            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.' and (nr, nc) not in visited:
                new_cost = cost + 1
                new_path = path + [(nr, nc)]
                heapq.heappush(pq, (new_cost + heuristic((nr, nc), goal), new_cost, (nr, nc), new_path))

