def solve(grid, start, goal):
    from functools import lru_cache

    if start == goal:
        return [start]

    rows, cols = len(grid), len(grid[0])
    if not (0 <= start[0] < rows and 0 <= start[1] < cols and 0 <= goal[0] < rows and 0 <= goal[1] < cols):
        return []

    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    @lru_cache(maxsize=None)
    def heuristic(pos):
        r, c = pos
        return abs(r - goal[0]) + abs(c - goal[1])

    def get_neighbors(pos):
        r, c = pos
        neighbors = []
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.':
                neighbors.append((nr, nc))
        return neighbors

    def search(path, g, limit):
        current = path[-1]
        if current == goal:
            return path
        f = g + heuristic(current)
        if f > limit:
            return f
        min_cost = float('inf')
        for neighbor in get_neighbors(current):
            if neighbor not in path:
                new_path = path + (neighbor,)
                result = search(new_path, g + 1, limit)
                if isinstance(result, list):
                    return result
                elif result < min_cost:
                    min_cost = result
        return min_cost

    limit = heuristic(start)
    while limit <= (rows + cols):
        result = search((start,), 0, limit)
        if isinstance(result, list):
            return result
        if result == float('inf'):
            return []
        limit = result
    return []
