from typing import List, Tuple, Set

def solve(grid: List[str], start: Tuple[int, int], goal: Tuple[int, int]) -> List[Tuple[int, int]]:
    rows, cols = len(grid), len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]  # Up, Down, Left, Right

    def is_valid(r: int, c: int) -> bool:
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    def heuristic(pos: Tuple[int, int]) -> int:
        return abs(pos[0] - goal[0]) + abs(pos[1] - goal[1])

    def ida_search(pos: Tuple[int, int], g: int, bound: int, visited: Set[Tuple[int, int]]) -> Tuple[str, List[Tuple[int, int]]]:
        if pos == goal:
            return "FOUND", [pos]
        h = heuristic(pos)
        if g + h > bound:
            return "CUTOFF", [pos]
        min_cost = sys.maxsize
        for dr, dc in directions:
            nr, nc = pos[0] + dr, pos[1] + dc
            if is_valid(nr, nc) and (nr, nc) not in visited:
                next_pos = (nr, nc)
                visited.add(next_pos)
                result, path = ida_search(next_pos, g + 1, bound, visited)
                visited.remove(next_pos)
                if result == "FOUND":
                    path.insert(0, pos)
                    return "FOUND", path
                if result == "CUTOFF":
                    min_cost = min(min_cost, g + 1 + h)
        return "CUTOFF", [pos]

    def idastar():
        visited = set()
        visited.add(start)
        bound = heuristic(start)
        result, path = ida_search(start, 0, bound, visited)
        if result == "FOUND":
            return path
        while True:
            bound = min(bound * 2, sys.maxsize)
            visited = set()
            visited.add(start)
            result, path = ida_search(start, 0, bound, visited)
            if result == "FOUND":
                return path
            if bound >= sys.maxsize:
                return []

    if not is_valid(*start) or not is_valid(*goal):
        return []
    if start == goal:
        return [start]
    return idastar()
