def solve(grid, start, goal):
    from collections import deque

    def is_wall(r, c):
        return not (0 <= r < len(grid) and 0 <= c < len(grid[0])) or grid[r][c] == '#'

    def jps_search(grid, start, goal):
        if is_wall(*start) or is_wall(*goal):
            return []
        if start == goal:
            return [start]

        def neighbors(pos):
            r, c = pos
            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]) and grid[nr][nc] == '.':
                    yield nr, nc

        def jump(pos, dir, goal):
            r, c = pos
            dr, dc = dir
            nr, nc = r + dr, c + dc
            if is_wall(nr, nc):
                return None
            if (nr, nc) == goal:
                return nr, nc
            # Force move
            if any(0 <= r + dr2 < len(grid) and 0 <= c + dc2 < len(grid[0]) and
                   grid[r + dr2][c + dc2] == '.' for dr2, dc2 in [(-1, 0), (1, 0), (0, -1), (0, 1)] if (dr2, dc2) != (dr, dc)):
                return nr, nc
            # Jump recursively
            next_pos = jump((nr, nc), dir, goal)
            return next_pos if next_pos else None

        visited = set()
        queue = deque()
        came_from = {}
        queue.append((start, None))
        while queue:
            pos, dir = queue.popleft()
            if pos in visited:
                continue
            visited.add(pos)
            if pos == goal:
                break
            for ndr, ndc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                if dir == (ndr, ndc):
                    continue
                npos = pos[0] + ndr, pos[1] + ndc
                if not is_wall(*npos) and npos not in visited:
                    jump_pos = jump(pos, (ndr, ndc), goal)
                    if jump_pos:
                        queue.append((jump_pos, (ndr, ndc)))
                        came_from[jump_pos] = pos

        if goal not in came_from:
            return []
        path = []
        curr = goal
        while curr != start:
            path.append(curr)
            curr = came_from[curr]
        path.append(start)
        path.reverse()
        return path

    return jps_search(grid, start, goal)
