        return 0 <= r < len(grid) and 0 <= c < len(grid[0]) and grid[r][c] == '.'

    def search(queue, visited, parent, dir_r, dir_c, goal_r, goal_c):
        r, c = queue.popleft()
        next_r, next_c = r + dir_r, c + dir_c
        if is_valid(next_r, next_c) and (next_r, next_c) not in visited:
            visited.add((next_r, next_c))
            parent[(next_r, next_c)] = (r, c)
            if (next_r, next_c) == (goal_r, goal_c):
                return True
            queue.append((next_r, next_c))
        return False

    def find_jump(r, c, dir_r, dir_c, goal_r, goal_c, visited):
        if not is_valid(r + dir_r, c + dir_c):
            return None
        while True:
            r += dir_r
            c += dir_c
            if not is_valid(r, c):
                return None
            if (r, c) == (goal_r, goal_c):
                return (r, c)
            if any(is_valid(r + dr, c + dc) for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)] if (r + dr, c + dc) != (r - dir_r, c - dir_c)):
                if (r, c) == (goal_r, goal_c) or not is_valid(r + dir_r, c + dir_c):
                    return (r, c)
                return (r, c)

    if not is_valid(*start) or not is_valid(*goal):
        return []
    if start == goal:
        return [start]

    dir_map = {
        'up': (-1, 0),
        'down': (1, 0),
        'left': (0, -1),
        'right': (0, 1)
    }

    parent = {}
    queue = deque([start])
    visited = {start}

    while queue:
        curr = queue[0]
        if curr == goal:
            break
        for name, (dr, dc) in dir_map.items():
            jump = find_jump(curr[0], curr[1], dr, dc, goal[0], goal[1], visited)
            if jump and jump not in visited:
                visited.add(jump)
                parent[jump] = curr
                queue.append(jump)

    if goal not in parent:
        return []

    path = []
    curr = goal
    while curr != start:
        path.append(curr)
        curr = parent[curr]
    path.append(start)
    path.reverse()
