            return (r, c)
        for ddr, ddc in directions:
            nr, nc = r + ddr, c + ddc
            if is_valid(nr, nc) and (ddr != -dr or ddc != -dc) and (nr, nc) != (r + dr, c + dc):
                if jump(r + dr, c + dc, dr, dc, (r, c)) is not None:
                    return (r + dr, c + dc)
        return None

    def get_path(start, goal):
        queue = [(start, 0, 0)]
        came_from = {}
        found = False
        path = []

        while queue:
            node, r, c = queue.pop(0)
            if node == goal:
                found = True
                break
            for dr, dc in directions:
                nr, nc = r + dr, c + dc
                if is_valid(nr, nc) and ((r + dr, c + dc)) not in came_from:
                    jumped = jump(r, c, dr, dc, node)
                    if jumped:
                        queue.append((node, jumped[0], jumped[1]))
                        came_from[jumped] = node

        if not found:
            return []

        current = goal
        while current != start:
            path.append(current)
            current = came_from.get(current)
        path.reverse()
        if path and path[0] != start:
            path.insert(0, start)
        return path if path and path[-1] == goal else []

    if not is_valid(*start) or not is_valid(*goal):
        return []
    if start == goal:
        return [start]
    return get_path(start, start)
