    def is_wall(r, c):
        return not (0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'))

    def search(state):
        r, c = state
        if (r, c) == goal:
            return True
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if not is_wall(nr, nc) and (nr, nc) not in parent:
                parent[(nr, nc)] = (r, c)
                if search((nr, nc)):
                    return True
        return False

    def jump_search(node, dir):
        r, c = node
        dr, dc = dir
        while 0 <= r + dr < rows and 0 <= c + dc < cols and grid[r + dr][c + dc] == '.':
            r += dr
            c += dc
            if (r, c) == goal or any(0 <= r + jdr < rows and 0 <= c + jdc < cols and grid[r + jdr][c + jdc] == '.' and (jdr, jdc) != dir for jdr, jdc in directions):
                break
        if 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.':
            return (r, c)
        return None

    def heuristic(a):
        return abs(a[0] - goal[0]) + abs(a[1] - goal[1])

    frontier = [(heuristic(start), start)]
    visited = set()
    parent = {}

    while frontier:
        _, current = heapq.heappop(frontier)
        visited.add(current)
        r, c = current
        if current == goal:
            path = []
            while current in parent:
                path.append(current)
                current = parent[current]
            path.append(current)
            path.reverse()
            return path
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.':
                next_state = (nr, nc)
                if next_state not in visited:
                    jump_to = jump_search(next_state, (dr, dc))
                    if jump_to is not None:
                        if jump_to in visited:
                            continue
                        if jump_to in parent:
                            parent[jump_to] = (r, c)
                            heapq.heappush(frontier, (heuristic(jump_to), jump_to))
                        else:
                            parent[(nr, nc)] = current
                            heapq.heappush(frontier, (heuristic(next_state), next_state))
    return []

def update_manhattan_neighbors(grid, neighbors, dr, dc):
    rows = len(grid)
    cols = len(grid[0])
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == '.':  # only for free cells
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    neighbors[(dr, dc)].add((nr, nc))
                else:
                    neighbors[(dr, dc)].add(None)
    return len(neighbors[(dr, dc)]), max(len(ns) for ns in neighbors.values())
