                if dr != 0 and dc != 0:
                    corner_directions = [(-dr, dc), (dr, -dc)]
                    for cdir in corner_directions:
                        cnr, cnc = nr + cdir[0], nc + cdir[1]
                        if 0 <= cnr < rows and 0 <= cnc < cols and grid[cnr][cnc] == '.':
