    if not (0 <= next_r < len(grid) and 0 <= next_c < len(grid[0]) and grid[next_r][next_c] == '.'):
        return None

    if dr != 0 and dc != 0:  # Diagonal movement
        # Vertical first
        result = jump(grid, (r + dr, c), goal, (dr, 0))
        if result:
            return result
        # Horizontal
        result = jump(grid, (r, c + dc), goal, (0, dc))
        if result:
