            if is_valid(nr, nc):
                neighbors.append((nr, nc))
        return neighbors

    def straight(r, c, dr, dc):
        step = 1
        while 0 <= r + step*dr < rows and 0 <= c + step*dc < cols:
            if grid[r + step*dr][c + step*dc] == '#':
                return None
            step += 1
        return r + (step - 1)*dr, c + (step - 1)*dc

    def diagonal(r, c, dr, dc):
        if 0 <= r + dr < rows and 0 <= c + dc < cols and grid[r + dr][c + dc] == '#':
            return None
        if not is_valid(r + dr, c) or not is_valid(r, c + dc):
            return None
        return r + dr, c + dc

    def jump(r, c, dr, dc, parent=None):
        if (r, c) == goal:
