                return next_r, next_c
            return jump(next_r, next_c, dr, dc, (r, c))
        else:  # diagonal
            if (is_valid(r + dr, c) and is_valid(r, c + dc)) or (not is_valid(r + dr, c) and not is_valid(r, c + dc)):
