                    return next_r, next_c
                if not is_valid(next_r - dr, next_c) or not is_valid(next_r, next_c - dc) or not is_valid(next_r - dr, next_c - dc):
                    return next_r, next_c
                return jump(next_r, next_c, dr, dc, (r, c))
            else:
                return None

