                if jump:
                    jumps.append(jump)
                    nr, nc = jump
                else:
                    n = [(nr + dr, nc), (nr, nc + dc), (nr + dr, nc + dc)]
                    if any(grid[ny][nx] == '#' for (ny, nx) in n if 0 <= ny < len(grid) and 0 <= nx < len(grid[0])):
