            if grid[nr][nc] == '#':
                continue
            if jump(r + dirr, c + dirc, dirr, dirc) is not None:
                return (r + dirr, c + dirc)
        return None

    def jump(r, c, dr, dc):
        if not (0 <= r < len(grid) and 0 <= c < len(grid[0])):
            return None
        if grid[r][c] == '#':
            return None
        if (dr, dc) == (0, 1):
            direction = 'R'
        elif (dr, dc) == (0, -1):
            direction = 'L'
        elif (dr, dc) == (1, 0):
            direction = 'D'
        elif (dr, dc) == (-1, 0):
