                    grid[nr][nc] == '#' for (nr, nc) in [(r + 1, c + dc), (r - 1, c + dc), (r, c + 2 * dc)]) and
                    grid[r][c + 2 * dc] == '.'):
                return (r, c)
        return jump(r + dr, c + dc, dr, dc)

    def bfs():
