            return (r + dir_r, c + dir_c)

        if is_straight_line(r, c, dir_r, dir_c):
            return (r + dir_r, c + dir_c)

        if is_straight_line(r, c, dir_r, dir_c):
            return (r + dir_r, c + dir_c)

        if grid[r + dir_r][c + dir_c] == '#':
            return None

        next_r, next_c = r + dir_r, c + dir_c
        next_dir, _ = get_dir(dir_r, dir_c)

        for d_index, (dr, dc) in enumerate(directions):
            if d_index % 2 == (dir_index % 2) + 1:  # Looking in perpendicular direction
                dir_name, _ = get_dir(dr, dc)
                res = jump(grid, next_r, next_c, dr, dc)
                if res:
                    return res

        return jump(grid, next_r, next_c, dir_r, dir_c)

    def neighbors(r, c, prev_dir=None):
        candidates = []
        for d_index, (dr, dc) in enumerate(directions):
            nr, nc = r + dr, c + dc
            if is_valid(nr, nc):
                dir_name, _ = get_dir(dr, dc)
                if prev_dir is None or dir_name != prev_dir and dir_name != opposite_dir(prev_dir):
                    jump_result = jump(grid, r, c, dr, dc)
                    if jump_result:
                        jumpr, jumnc = jump_result
                        if is_valid(jumpr, jumnc):
                            heapq.heappush(candidates, ((jumnc - c) ** 2 + (jumpr - r) ** 2, jumnr, jumnc, dir_name))
        return candidates

    visited = set()
    queue = [(0, start[0], start[1], None)]  # (cost, row, col, direction)
    prev = {start: None}

    while queue:
        _, r, c, prev_dir = heapq.heappop(queue)
        if (r, c) in visited:
            continue
        visited.add((r, c))

        if (r, c) == goal:
            break

        for _, nr, nc, dir_name in neighbors(r, c, prev_dir):
            if (nr, nc) not in visited:
                prev[(nr, nc)] = (r, c)
                heapq.heappush(queue, ((nc - c) ** 2 + (nr - r) ** 2, nr, nc, dir_name))

    if goal not in prev:
        return []

    # Reconstruct path
    path = []
    at = goal
    while at is not None:
        path.append(at)
        at = prev[at]
    path.reverse()
    return path if path and path[0] == start else []
