import heapq

def solve(grid, start, goal):
    rows = len(grid)
    cols = len(grid[0])

    if start == goal and grid[start[0]][start[1]] == '.':
        return [start]

    for r, c in [start, goal]:
        if not (0 <= r < rows and 0 <= c < cols) or grid[r][c] == '#':
            return []

    def is_free(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    def get_neighbors(r, c, dr, dc):
        neighbors = []
        r += dr
        c += dc
        while is_free(r, c):
            neighbors.append((r, c))
            if dr != 0 and dc != 0:  # diagonal move
                if is_free(r, c - dc) and (r, c - dc) not in neighbors:
                    if is_free(r - dr, c - dc) or not is_free(r - dr, c):
                        neighbors.append((r, c - dc))
                if is_free(r - dr, c) and (r - dr, c) not in neighbors:
                    if is_free(r - dr, c - dc) or not is_free(r, c - dc):
                        neighbors.append((r - dr, c))
            r += dr
            c += dc
        return neighbors

    def heuristic(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    open_set = []
    heapq.heappush(open_set, (0, start))
    came_from = {}
    g_score = {start: 0}
    f_score = {start: heuristic(start, goal)}

    while open_set:
        _, current = heapq.heappop(open_set)

        if current == goal:
            path = [current]
            while current in came_from:
                current = came_from[current]
                path.append(current)
            return list(reversed(path))

        for dirr, dirc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:  # only orthogonal to avoid unnecessary complexity
            neighbors = get_neighbors(current[0], current[1], dirr, dirc)
            for node in neighbors:
                nr, nc = node
                tentative_g = g_score[current] + 1
                if is_free(nr, nc) and (nr, nc) not in g_score:
                    came_from[(nr, nc)] = current
                    g_score[(nr, nc)] = tentative_g
                    f_score[(nr, nc)] = tentative_g + heuristic((nr, nc), goal)
                    heapq.heappush(open_set, (f_score[(nr, nc)], (nr, nc)))

    return []
