    def astar(start, goal, reverse=False):
        visited = {}
        queue = [(0, start)]
        came_from = {}

        while queue:
            _, current = heapq.heappop(queue)
            if current in visited:
                continue
            visited[current] = None
            if current == goal:
                break
            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                r, c = current[0] + dr, current[1] + dc
                if is_valid(r, c) and (reverse or ((r, c) not in visited)):
                    if reverse:
                        next_cell = (r, c)
                        parent = current
                    else:
                        next_cell = (r, c)
                        parent = current
                    if next_cell not in visited:
                        came_from[next_cell] = parent
                        heapq.heappush(queue, (heuristic(next_cell, goal), next_cell))
        return visited, came_from

    if start == goal and grid[start[0]][start[1]] == '.':
        return [start]
    if not is_valid(*start) or not is_valid(*goal):
        return []

    _, came_from_forward = astar(start, goal)
    _, came_from_backward = astar(goal, start, reverse=True)

    for key in came_from_forward:
        if key in came_from_backward:
            path = [key]
            curr = came_from_forward[key]
            while curr != start:
                path.insert(0, curr)
                curr = came_from_forward[curr]
            curr = came_from_backward[key]
            while curr != goal:
                path.append(curr)
                curr = came_from_backward[curr]
            return path
    return []
