    if start == goal:
        return [start]

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]  # Up, Down, Left, Right

    dist = [[float('inf')] * cols for _ in range(rows)]
    dist[start[0]][start[1]] = 0
    pq = [(0, start[0], start[1])]
    parent = [[None] * cols for _ in range(rows)]

    def is_valid(x, y):
        return 0 <= x < rows and 0 <= y < cols and grid[x][y] == '.'

    def diagonal(x1, y1, x2, y2):
        return ((x1 + x2) % 2 == 0) and ((y1 + y2) % 2 == 0) and is_valid(x1, y1) and is_valid(x2, y2)

    def jump(x, y, dx, dy):
        if not is_valid(x, y):
            return None
        if (x, y) == goal:
            return (x, y)
        nx, ny = x + dx, y + dy
        if not is_valid(nx, ny):
            return None
        # Check straight jump
        if dx != 0 and dy != 0:
            if is_valid(x + dx, y) or is_valid(x, y + dy):
                if is_valid(nx, ny):
                    result = jump(nx, ny, dx, dy)
                    if result:
                        return result
        else:
            if is_valid(nx, ny):
                result = jump(nx, ny, dx, dy)
                if result:
                    return result
        return (x, y)

    def get_neighbors(x, y):
        neighbors = []
        for dx, dy in directions:
            if dx == 0 and dy == 0:
                continue
            if is_valid(x + dx, y + dy):
                n = jump(x, y, dx, dy)
                if n and dist[n[0]][n[1]] == float('inf'):
                    neighbors.append(n)
        return neighbors

    while pq:
        _, x, y = heapq.heappop(pq)
        if (x, y) == goal:
            break
        for nx, ny in get_neighbors(x, y):
            if dist[x][y] + 1 < dist[nx][ny]:
                dist[nx][ny] = dist[x][y] + 1
                parent[nx][ny] = (x, y)
                heapq.heappush(pq, (dist[nx][ny], nx, ny))

    if not parent[goal[0]][goal[1]]:
        return []

    path = []
    curr = goal
    while curr:
        path.append(curr)
        curr = parent[curr[0]][curr[1]]
    return path[::-1]
