        return []

    if start == goal:
        return [start]

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def is_valid(x, y):
        return 0 <= x < len(grid) and 0 <= y < len(grid[0]) and grid[x][y] == '.'

    def is_corner(x, y, dx, dy):
        if not is_valid(x + dx, y + dy):
            return False
        if dx != 0 and dy != 0:
            return not is_valid(x + dy, y + dx)
        if dx != 0:
            return not (is_valid(x, y + dy) or is_valid(x + dx, y) or is_valid(x + dx, y + dy))
        if dy != 0:
            return not (is_valid(x + dx, y) or is_valid(x, y + dy) or is_valid(x + dx, y + dy))
        return False

    def is_turn(x, y):
        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
        free_dirs = [(dx, dy) for dx, dy in directions if is_valid(x + dx, y + dy)]
        return len(free_dirs) >= 2

    def jump(x, y, dx, dy, prev_dx=0, prev_dy=0):
        if not is_valid(x, y):
            return None
        if (x, y) == goal:
            return (x, y)
        if is_corner(x, y, dx, dy):
            return (x, y)

        next_x = x + dx
        next_y = y + dy
        result = jump(next_x, next_y, dx, dy, dx, dy)
        if result is not None:
            return result

        if dx != 0 or dy != 0:
            for alt_dx, alt_dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                if (alt_dx != 0 and dy != 0 and alt_dy != 0) or (alt_dy != 0 and dx != 0 and alt_dx != 0):
                    if alt_dx != dx or alt_dy != dy:
                        alt_result = jump(x + alt_dx, y + alt_dy, alt_dx, alt_dy, alt_dx, alt_dy)
                        if alt_result:
                            return (x + alt_dx, y + alt_dy)

        return None

    visited = set()

    from collections import deque

    queue = deque([(0, start, None)])

    path_map = dict()

    while queue:
        dist, node, parent = queue.popleft()
        if node in visited:
            continue
        visited.add(node)
        path_map[node] = parent
        if node == goal:
            path = []
            while node:
                path.append(node)
                node = path_map[node]
            path.reverse()
            return path

        for dx, dy in directions:
            next_node = (node[0] + dx, node[1] + dy)
            if next_node not in visited and is_valid(next_node[0], next_node[1]):
                j_node = jump(node[0] + dx, node[1] + dy, dx, dy)
                if j_node:
                    queue.append((dist + 1, j_node, node))

    return []
