            nr, nc = r + dr, c + dc
            if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]) and is_free(grid, (nr, nc)):
                yield (nr, nc)

    def forward_search(frontier, visited):
        while frontier:
            pos = frontier.popleft()
            if pos in reverse_visited:
                return build_path(forward_parent, reverse_parent, pos)
            for next_pos in neighbors(pos):
                if next_pos not in forward_visited:
                    forward_visited.add(next_pos)
                    forward_parent[next_pos] = pos
                    frontier.append(next_pos)

    def backward_search(frontier, visited):
        while frontier:
            pos = frontier.popleft()
            if pos in forward_visited:
                return build_path(forward_parent, reverse_parent, pos)
            for next_pos in neighbors(pos):
                if next_pos not in reverse_visited:
                    reverse_visited.add(next_pos)
                    reverse_parent[next_pos] = pos
                    frontier.append(next_pos)

    def build_path(fwd_parent, rev_parent, meeting_point):
        path = [meeting_point]
        while path[-1] != start:
            path.append(fwd_parent[path[-1]])
        path.reverse()
        current = path[-1]
        while current != goal:
            current = rev_parent[current]
            path.append(current)
        return path

    def is_free(grid, pos):
        r, c = pos
        return 0 <= r < len(grid) and 0 <= c < len(grid[r]) and grid[r][c] == '.'

    forward_parent, reverse_parent = {}, {}
    forward_visited, reverse_visited = set([start]), set([goal])
    forward_queue, reverse_queue = deque([start]), deque([goal])

    while forward_queue and reverse_queue:
        path = forward_search(forward_queue, forward_visited)
        if path:
            return path
        path = backward_search(reverse_queue, reverse_visited)
        if path:
            return path

