import heapq

def solve(grid, start, goal):
    if not grid or not grid[0]:
        return []

    rows = len(grid)
    cols = len(grid[0])

    if start == goal:
        return [start] if grid[start[0]][start[1]] == '.' else []

    def is_free(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    def get_neighbors(r, c):
        neighbors = [(r + dr, c + dc) for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]]
        return [(nr, nc) for nr, nc in neighbors if is_free(nr, nc)]

    def heuristic(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def a_star(start, goal, get_neighbors, heuristic):
        open_set = [(0, start)]
        came_from = {}
        g_score = {start: 0}
        f_score = {start: heuristic(start, goal)}

        while open_set:
            _, current = heapq.heappop(open_set)
            if current == goal:
                break
            for neighbor in get_neighbors(*current):
                tentative_g = g_score[current] + 1
                if neighbor not in g_score or tentative_g < g_score[neighbor]:
                    came_from[neighbor] = current
                    g_score[neighbor] = tentative_g
                    f_score[neighbor] = tentative_g + heuristic(neighbor, goal)
                    heapq.heappush(open_set, (f_score[neighbor], neighbor))
        return came_from

    if not is_free(*start) or not is_free(*goal):
        return []

    came_from_forward = a_star(start, goal, lambda r, c: get_neighbors(r,c), heuristic)
    came_from_backward = a_star(goal, start, lambda r, c: get_neighbors(r,c), heuristic)

    def reconstruct_path(came_from, start, goal):
        path = []
        current = goal
        while current != start:
            path.append(current)
            if current not in came_from:
                return []
            current = came_from[current]
        path.append(start)
        return path[::-1]

    forward_path = reconstruct_path(came_from_forward, start, goal)
    backward_path = reconstruct_path(came_from_backward, goal, start) + [start]

    if forward_path:
        return forward_path
    elif backward_path:
        return backward_path
    else:
        return []
