                        cost_so_far[next_cell] = new_cost
                        priority = new_cost + heuristic(goal, next_cell)
                        heapq.heappush(frontier, (priority, next_cell))
                        came_from[next_cell] = current

        if goal not in came_from:
            return None

        path = []
        current = goal
        while current:
            path.append(current)
