import heapq

def solve(grid, start, goal):
    if (
        not grid or 
        not 0 <= start[0] < len(grid) or 
        not 0 <= start[1] < len(grid[0]) or 
        not 0 <= goal[0] < len(grid) or 
        not 0 <= goal[1] < len(grid[0]) or 
        grid[start[0]][start[1]] == '#' or 
        grid[goal[0]][goal[1]] == '#'
    ):
        return []

    if start == goal:
        return [start]

    rows, cols = len(grid), len(grid[0])

    def get_neighbors(pos):
        r, c = pos
        neighbors = []
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if (0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.'):
                neighbors.append((nr, nc))
        return neighbors

    def heuristic_cost(pos, target):
        pr, pc = pos
        tr, tc = target
        return abs(pr - tr) + abs(pc - tc)

    def a_star(frontier, came_from, g_cost, end, is_forward):
        while frontier:
            cost, current = heapq.heappop(frontier)
            if current == end:
                path = []
                while current in came_from:
                    path.append(current)
                    current = came_from[current]
                return path[::-1] if is_forward else path
            for neighbor in get_neighbors(current):
                new_cost = g_cost[current] + 1
                if neighbor not in g_cost or new_cost < g_cost[neighbor]:
                    g_cost[neighbor] = new_cost
                    h = heuristic_cost(neighbor, end)
                    f = new_cost + h
                    heapq.heappush(frontier, (f, neighbor))
                    came_from[neighbor] = current
        return None

    g_cost_forward = {start: 0}
    came_from_forward = {}
    frontier_forward = [(heuristic_cost(start, goal), start)]

    g_cost_backward = {goal: 0}
    came_from_backward = {}
    frontier_backward = [(heuristic_cost(goal, start), goal)]

    while frontier_forward and frontier_backward:
        path_forward = a_star(frontier_forward, came_from_forward, g_cost_forward, goal, True)
        path_backward = a_star(frontier_backward, came_from_backward, g_cost_backward, start, False)
        if path_forward:
            return path_forward
        if path_backward:
            full_path = [start] + path_backward
            return full_path

        if frontier_backward:
            cost, f = heapq.heappop(frontier_forward)
            g_cost_forward[f] = cost - heuristic_cost(f, goal)
        if frontier_forward:
            cost, b = heapq.heappop(frontier_backward)
            g_cost_backward[b] = cost - heuristic_cost(b, start)

    return []
