import heapq

def solve(grid, start, goal):
    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0

    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    def heuristic(pos, target):
        return abs(pos[0] - target[0]) + abs(pos[1] - target[1])

    def retrace_path(came_from_forward, came_from_backward, meeting_point):
        path = [meeting_point]
        curr = meeting_point
        while curr in came_from_forward:
            curr = came_from_forward[curr]
            path.insert(0, curr)
        curr = meeting_point
        while curr in came_from_backward:
            curr = came_from_backward[curr]
            path.append(curr)
        return path

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    if start == goal:
        if is_valid(*start):
            return [start]
        else:
            return []

    if not (is_valid(*start) and is_valid(*goal)):
        return []

    open_forward = [(0, start)]
    open_backward = [(0, goal)]

    came_from_forward = {}
    came_from_backward = {}

    g_forward = {start: 0}
    g_backward = {goal: 0}

    while open_forward and open_backward:
        # Forward step
        _, curr = heapq.heappop(open_forward)
        for dr, dc in directions:
            new = (curr[0] + dr, curr[1] + dc)
            if is_valid(*new) and new not in g_forward:
                g_forward[new] = g_forward[curr] + 1
                f = g_forward[new] + heuristic(new, goal)
                heapq.heappush(open_forward, (f, new))
                came_from_forward[new] = curr

                if new in g_backward:
                    return retrace_path(came_from_forward, came_from_backward, new)

        # Backward step
        _, curr = heapq.heappop(open_backward)
        for dr, dc in directions:
            new = (curr[0] + dr, curr[1] + dc)
            if is_valid(*new) and new not in g_backward:
                g_backward[new] = g_backward[curr] + 1
                f = g_backward[new] + heuristic(new, start)
                heapq.heappush(open_backward, (f, new))
                came_from_backward[new] = curr

                if new in g_forward:
                    return retrace_path(came_from_forward, came_from_backward, new)

    return []
