        for nr, nc in [(r-1,c), (r+1,c), (r,c-1), (r,c+1)]:
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.':
                yield (nr, nc)

    def a_star(front, back, forward=True):
        if forward:
            frm, to = front, back
        else:
            frm, to = back, front
        heap = [(heuristic(frm, to), 0, heuristic(frm, to), frm, [frm])]
        visited = {frm}
        while heap:
            _, g, _, pos, path = heappop(heap)
            if pos == to:
                return path
            for next_pos in neighbors(pos):
                if next_pos not in visited:
                    new_g = g + 1
                    new_h = heuristic(next_pos, to)
                    new_f = new_g + new_h
                    heappush(heap, (new_f, new_g, new_h, next_pos, path + [next_pos]))
                    visited.add(next_pos)
        return None

    forward_path = a_star(start, goal, forward=True)
    if forward_path is not None:
        return forward_path
    backward_path = a_star(goal, start, forward=False)
