            if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]) and grid[nr][nc] == '.':
                yield nr, nc

    def heuristic(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def search(start, goal, forward):
        queue = [(heuristic(start, goal), start, [start])]
        visited = set([start])
        parent = {start: None}

        while queue:
            _, current, path = queue.pop(0)
            if current == goal:
                return path

            for next_pos in neighbors(current):
                if next_pos not in visited:
                    visited.add(next_pos)
                    parent[next_pos] = current
                    queue.append((heuristic(next_pos, goal if forward else start), next_pos, path + [next_pos]))
                    if next_pos == goal:
                        return path + [next_pos]
        return None

    forward_path = search(start, goal, forward=True)
    backward_path = search(goal, start, forward=False)

    if forward_path is None or backward_path is None:
        return []

    # Combine paths, removing the duplicated intersection point
    i = 0
    while i < len(backward_path) and backward_path[i] in forward_path:
        i += 1
    intersection = backward_path[i - 1]
    index_in_forward = forward_path.index(intersection)

    backward_path.reverse()
    return forward_path[:index_in_forward + 1] + backward_path[1:]

    # Direct check for start == goal and not a wall
    if start == goal:
        return [start] if grid[start[0]][start[1]] == '.' else []
