        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def a_star(start, goal, reverse=False):
        heap = [(0, start)]
        came_from = {}
        cost = {start: 0}
        while heap:
            _, current = heapq.heappop(heap)
            if current == goal:
                break
            for dr, dc in directions:
                if reverse:
                    nr, nc = current[0] + dr, current[1] + dc
                    if not is_valid(nr, nc):
                        continue
                    neighbor = (nr, nc)
                    if current in came_from and neighbor == came_from[current]:
                        continue
                else:
                    nr, nc = current[0] - dr, current[1] - dc
                    if not is_valid(nr, nc):
                        continue
                    neighbor = (nr, nc)
                    if current in came_from and neighbor == came_from[current]:
                        continue
                new_cost = cost[current] + 1
                if neighbor not in cost or new_cost < cost[neighbor]:
                    cost[neighbor] = new_cost
                    priority = new_cost + abs(neighbor[0] - goal[0]) + abs(neighbor[1] - goal[1])
                    heapq.heappush(heap, (priority, neighbor))
                    came_from[neighbor] = current
        return came_from

    came_from_start = a_star(start, goal)
    came_from_goal = a_star(goal, start, reverse=True)

    common_nodes = set(came_from_start.keys()) & set(came_from_goal.keys())
    if not common_nodes:
        return []
    meet = min(common_nodes, key=lambda n: (len(path_from_start(n)) + len(path_from_goal(n))), default=None)

    def path_from_start(node):
        path = []
        while node in came_from_start:
            path.append(node)
            node = came_from_start[node]
        return path[::-1]

    def path_from_goal(node):
        path = []
        while node in came_from_goal:
            path.append(node)
            node = came_from_goal[node]
