        came_from = {}
        dist = {start: 0}

        queue = deque([start])
        while queue:
            current = queue.popleft()
            if current == goal:
                break
            for next in get_neighbors(current):
                new_dist = dist[current] + 1
                if next not in dist or new_dist < dist[next]:
                    came_from[next] = current
                    dist[next] = new_dist
                    open_set.discard(next)
                    if next not in open_set:
                        open_set.add(next)
                        queue.append(next)
        return came_from, dist.get(goal, float('inf'))

