        or grid[start[0]][start[1]] == "#"
        or not (0 <= goal[0] < len(grid) and 0 <= goal[1] < len(grid[0]))
        or grid[goal[0]][goal[1]] == "#"
    ):
        return []

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def heuristic(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    class BidirectionalAStar:
        def __init__(self, start, goal):
            self.origin = start
            self.goal = goal
            self.queue = [(heuristic(start, goal), 0, start, None)]
            self.visited = {start: None}
            self.cost = {start: 0}

        def get_path(self, other_search):
            if not self.visited or not other_search.visited:
                return []

            meeting_point = None
            for (a, b), path_data in self.visited.items():
                if a == b:
                    continue
                if (a, b) in other_search.visited:
                    meeting_point = (a, b)
                    break

            if meeting_point is None:
                return []

            path = []
            current = meeting_point
            while current is not None:
                path.append(current)
                current = self.visited[current]

            path.reverse()

            current = other_search.visited[meeting_point]
            while current is not None:
                path.append(current)
                current = other_search.visited[current]

            return path

        def search(self):
            while self.queue:
                _, g, node, parent = heapq.heappop(self.queue)

                if node in self.visited and self.visited[node] is not None:
                    continue

                self.visited[node] = parent
                self.cost[node] = g

                if node == self.goal:
                    break

                for dx, dy in directions:
                    nx, ny = node[0] + dx, node[1] + dy
                    if (
                        0 <= nx < len(grid)
                        and 0 <= ny < len(grid[0])
                        and grid[nx][ny] == "."
                    ):
                        next_node = (nx, ny)
                        new_g = g + 1
                        if next_node not in self.visited or new_g < self.cost.get(next_node, float('inf')):
                            heapq.heappush(
                                self.queue,
                                (new_g + heuristic(next_node, self.goal), new_g, next_node, node)
                            )

    forward_search = BidirectionalAStar(start, goal)
    backward_search = BidirectionalAStar(goal, start)

    while forward_search.queue or backward_search.queue:
        if forward_search.queue:
            _, f, node, parent = heapq.heappop(forward_search.queue)
            if node not in forward_search.visited or forward_search.cost[node] > f - heuristic(node, forward_search.goal):
                forward_search.visited[node] = parent
                forward_search.cost[node] = f - heuristic(node, forward_search.goal)
                for dx, dy in directions:
                    nx, ny = node[0] + dx, node[1] + dy
                    if (
                        0 <= nx < len(grid)
                        and 0 <= ny < len(grid[0])
                        and grid[nx][ny] == "."
                    ):
                        next_node = (nx, ny)
                        new_g = f - heuristic(node, forward_search.goal) + 1
                        if next_node not in forward_search.visited or new_g < forward_search.cost.get(next_node, float('inf')):
                            heapq.heappush(
                                forward_search.queue,
                                (new_g + heuristic(next_node, forward_search.goal), new_g + heuristic(next_node, forward_search.goal), next_node, node)
                            )

        if backward_search.queue:
            _, f, node, parent = heapq.heappop(backward_search.queue)
            if node not in backward_search.visited or backward_search.cost[node] > f - heuristic(node, backward_search.goal):
                backward_search.visited[node] = parent
                backward_search.cost[node] = f - heuristic(node, backward_search.goal)
                for dx, dy in directions:
                    nx, ny = node[0] + dx, node[1] + dy
                    if (
                        0 <= nx < len(grid)
                        and 0 <= ny < len(grid[0])
                        and grid[nx][ny] == "."
                    ):
                        next_node = (nx, ny)
                        new_g = f - heuristic(node, backward_search.goal) + 1
                        if next_node not in backward_search.visited or new_g < backward_search.cost.get(next_node, float('inf')):
                            heapq.heappush(
                                backward_search.queue,
                                (new_g + heuristic(next_node, backward_search.goal), new_g + heuristic(next_node, backward_search.goal), next_node, node)
                            )

        path = forward_search.get_path(backward_search)
        if path:
            if path[0] == start and path[-1] == goal:
                return path
            if path[0] == start and path[-1] == start:
                return [start]
            if path[0] == start and path[-1] != goal:
                corrected_path = [start]
                n = len(path) // 2
                current = path[n]
                while current != goal:
                    corrected_path.append(current)
                    for dx, dy in directions:
                        nx, ny = current[0] + dx, current[1] + dy
                        if (nx, ny) in forward_search.visited and (nx, ny) not in corrected_path:
                            current = (nx, ny)
                            break
                corrected_path.append(goal)
                if all(grid[p[0]][p[1]] == '.' for p in corrected_path) and all(
                    abs(corrected_path[i][0] - corrected_path[i + 1][0]) + abs(corrected_path[i][1] - corrected_path[i + 1][1]) == 1
                    for i in range(len(corrected_path) - 1)
                ):
                    return corrected_path

    return forward_search.get_path(backward_search)
