        open_set = []
        heapq.heappush(open_set, (0, start))
        came_from = {}
        g_score = {start: 0}
        f_score = {start: heuristic(start, goal)}
        nodes = {start}

        while open_set:
            _, current = heapq.heappop(open_set)
            if current == goal:
                path = rebuild_path(came_from, current)
                return path, {node: g_score[node] for node in nodes}

            nodes.add(current)
            for neighbor in neighbors(current):
                tentative_g = g_score[current] + 1
                if neighbor not in g_score or tentative_g < g_score[neighbor]:
                    came_from[neighbor] = current
                    g_score[neighbor] = tentative_g
                    f_score[neighbor] = tentative_g + heuristic(neighbor, goal)
                    heapq.heappush(open_set, (f_score[neighbor], neighbor))

        return None, {}

    def rebuild_path(came_from, current):
        path = [current]
        while current in came_from:
            current = came_from[current]
            path.append(current)
        return path

    def is_free(grid, r, c):
        return 0 <= r < len(grid) and 0 <= c < len(grid[0]) and grid[r][c] == '.'

    path1, g1 = a_star(start, goal, False)
    path2, g2 = a_star(goal, start, True)

    if not path1 and not path2:
        return []

    overlap = set(g1).intersection(set(g2))
    merge_point = min(overlap, key=lambda x: g1[x] + g2[x])  # Find common node with minimal total cost

    path1_rev = path1[::-1] if path1 and path1[-1] == goal else []
    path2_for = path2 if path2 and path2[-1] == start else []

    if merge_point == start or merge_point == goal:
        if path1:
            return path1
        return path2[::-1]

    idx1 = path1_rev.index(merge_point)
    idx2 = path2_for.index(merge_point)

    full_path = path2_for[:idx2+1] + path1_rev[idx1+1:][::-1]

    return full_path
